(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["ko"] = {"ui":{"lead":"게임은 어떻게 발견되고, 잊히고, 해독되고, 바뀌어 왔을까요? {n}편의 이야기를 읽고 마지막 퀴즈를 모두 맞히면 스탬프를 받을 수 있어요.","card":"스탬프 카드","cardN":"{n} / {of}개 모음","cardAll":"모두 모았어요!","no":"이야기 {n}","mins":"약 {n}분","stamped":"스탬프 완료","back":"이야기 목록","quiz":"확인 퀴즈","links":"전시 보기・게임 하기","game":"게임","exhibit":"소장품","art":"그림","room":"전시실","room_chance":"우연의 도구","qn":"{n} / {of} 문제","right":"정답!","wrong":"아쉬워요… 정답에 표시했어요.","got":"스탬프를 찍었어요!","again":"모두 정답!","gotSub":"스탬프 카드에 기록되었어요.","missed":"{n}문제 틀렸어요","retrySub":"모두 맞혀야 스탬프를 받을 수 있어요. 이야기를 다시 읽고 도전해 보세요.","retry":"다시 도전","room_paint":"그림 속 게임","room_map":"지도","kfH":"이 이야기의 요점","tlH":"연표","refH":"출처·참고"},"ex":{"ur":"우르 왕실의 게임판","liubo":"육박 판과 말","pyrgus":"로마의 주사위 탑","sugoroku":"목화자단 쌍륙판","nishapur":"니샤푸르의 체스 세트","lewis":"루이스섬 체스 말","senet":"투탕카멘의 세네트 판","ballinderry":"밸린데리 게임판","goose":"체스와 거위 게임판","kofukuji":"고후쿠지 옛 경내 출토 쇼기 말","shosoin":"목화자단 바둑판"},"paint":{"liubo":"육박을 두는 두 사람(부장 인형)","sugoroku":"쌍륙을 두는 두 소녀","shahnama":"부주르그미흐르, 체스를 풀다","nefertari":"세네트를 두는 네페르타리 왕비","chaupar":"차우파르를 두는 시바와 파르바티","shogi":"쇼기를 두는 젊은 남녀","hydria":"놀이를 즐기는 아킬레우스와 아이아스(물항아리)","eakins":"체스 두는 사람들","weiqi":"바둑 두는 신선 무늬 접시","webb":"백개먼을 하는 두 사람(장식장)","liberale":"체스 두는 사람들"},"ur":{"title":"4500년 전의 규칙은 어떻게 해독되었나","lead":"우르 왕묘에서 나온 판에는 놀이법이 남아 있지 않았습니다. 단서는 2000여 년 뒤의 점토판에 있었습니다.","s":["1920년대에 레너드 울리는 이라크 남부 우르에서 왕족의 무덤을 발굴해, 조개껍데기와 청금석으로 장식한 20칸 게임판을 찾아냈습니다. 기원전 2600~2400년경의 것입니다. 비슷한 판이 중동 곳곳에서 나와, 오랫동안 널리 즐긴 게임이었음을 알 수 있습니다.","하지만 놀이법을 적은 기록은 함께 나오지 않았습니다. 판과 말과 주사위는 있는데 규칙을 모른다 — 고대 게임에서는 흔한 일입니다.","단서는 대영박물관 수장고에 있었습니다. 기원전 177/176년에 바빌론의 서기 이티-마르둑-발라투가 이딘-벨이라는 사람의 점토판을 베껴 쓴 쐐기문자 점토판입니다. 판보다 2000년 넘게 뒤의 기록이었습니다.","1980년대 초, 대영박물관의 어빙 핀켈은 이 점토판이 같은 20칸 게임에 관한 것임을 알아차렸습니다. 뒷면에는 판의 그림과 함께, 각 칸에 멈췄을 때의 길흉을 알리는 말이 적혀 있었습니다. 핀켈은 점토판의 내용과 판의 구조로부터 두 사람이 말을 경주시키는 놀이법을 복원했습니다.","이 복원 규칙은 지금 전 세계에서 즐기고 있습니다. 물론 우르의 왕족이 똑같이 놀았는지는 알 수 없습니다. 그래도 남인도의 코치에서는 1950년대까지 비슷한 게임을 했다고 알려져 있어, 이 게임의 긴 생명을 느끼게 합니다."],"quiz":[["놀이법의 단서가 된 점토판은 언제쯤 쓰였을까요?","기원전 2세기(판보다 2000년 이상 뒤)","판과 같은 기원전 2600년경","중세(12세기)","19세기"],["점토판을 해독해 놀이법을 복원한 사람은?","어빙 핀켈","하워드 카터","샹폴리옹","아서 에번스"],["점토판에는 칸에 멈췄을 때의 무엇이 적혀 있었을까요?","길흉(운세)","왕의 이름","세금 액수","별 이름뿐"]],"kf":["판은 기원전 2600~2400년경, 이라크 남부 우르의 왕릉에서 나왔다","놀이 방법은 2000년도 더 뒤의 점토판으로 복원되었다","칸은 20개, 말은 한쪽에 7개, 주사위는 사면체"],"more":[{"h":"왕릉과 ‘왕의 게임’","p":["울리가 우르 왕릉에서 찾은 20칸 판은 하나가 아니라 여러 개였습니다. 가장 유명한 판(대영박물관)은 나무판에 조개껍데기·붉은 석회암·청금석을 박은 것으로, ‘왕의 게임’이라는 이름은 여기서 왔습니다.","하지만 왕족만의 놀이는 아니었습니다. 같은 20칸 판이 메소포타미아에서 이집트, 동지중해까지 널리 발견되고, 아시리아 궁전에서는 문을 지키는 거대한 인두유익우상의 받침대에 경비병이 새긴 듯한 판까지 남아 있습니다."],"cap":["대영박물관의 ‘우르의 왕실 게임’. 소장품 전시실에서 3D로 돌려 볼 수 있습니다"]},{"h":"판의 구조","p":["20칸은 3×4의 12칸과 3×2의 6칸을 2칸짜리 좁은 ‘다리’로 이은 모양입니다. 꽃무늬(로제트) 칸이 5개 있는데, 복원 규칙에서는 여기에 멈추면 한 번 더 던질 수 있고, 잡히지 않는 안전한 칸이 됩니다.","주사위는 사면체로, 네 꼭짓점 중 둘에 표시가 있습니다. 4개를 던져 표시가 위로 온 수만큼 나아가므로 0~4가 나옵니다. 가장 잘 나오는 것은 2(16번에 6번), 0과 4는 16번에 1번뿐입니다. 박물관의 ‘우연의 도구’에서 직접 던져 볼 수 있습니다."],"cap":["20칸과 5개의 로제트(꽃무늬). 초록 숫자는 한쪽 말이 나아가는 순서(복원 규칙)","사면체 주사위 4개를 던졌을 때 나오는 비율(16가지 중)"]},{"h":"점토판이 말하는 것","p":["점토판 앞면에는 놀이 방법, 뒷면에는 판의 그림이 있고 칸마다 별자리 기호가 적혀 있었습니다. 칸에 멈췄을 때의 말은 ‘친구를 만난다’ ‘좋은 맥주를 마신다’ 같은 점괘 같아서, 이 게임이 운세와 이어져 있었음을 알 수 있습니다.","다만 점토판은 일부가 깨져 모든 규칙을 읽을 수는 없습니다. 핀켈의 복원은 읽을 수 있는 부분과 판의 모양으로 가장 앞뒤가 맞는 놀이법을 짜 맞춘 것이고, 학자들 사이에는 다른 복원안도 있습니다."]},{"h":"인도에 남은 마지막 놀이꾼","p":["핀켈은 뒤에, 인도 남부 코치(코친)에 살던 유대인 공동체가 아주 최근까지 20칸 게임을 했다는 사실을 알게 되었습니다. 판의 모양도 많이 닮았습니다.","그들이 1950년대에 이스라엘로 옮겨 가기 전까지 이 게임은 집집마다 이어져 왔습니다. 고대 교역로를 따라 인도까지 전해져 4000년 넘게 살아남았는지도 모릅니다."]}],"tl":[["기원전 2600~2400년경","우르 왕릉에 20칸 판이 묻힌다"],["기원전 8세기","아시리아 궁전 문지기 상의 받침에 판이 새겨진다"],["기원전 177/176년","바빌론의 서기가 규칙의 점토판을 베껴 쓴다"],["1922~1934년","울리가 우르를 발굴해 판을 찾는다"],["1980년대 초","핀켈이 점토판을 해독해 규칙을 복원한다"],["1950년대까지","인도 남부 코치에서 아주 비슷한 게임을 한다"]]},"liubo":{"title":"육박은 왜 사라졌을까","lead":"한나라 때 황제부터 서민까지 빠져들었던 게임이, 몇백 년 만에 놀이법째 잊히고 말았습니다.","s":["육박은 한나라(기원전 206~기원후 220년) 때 중국에서 크게 유행한 게임입니다. 무덤에 넣은 인형과 화상석, 거울 무늬에까지 그 모습이 남아 있고, 신선이 육박을 두는 장면도 자주 그려졌습니다.","그런데 한나라가 무너지자 육박은 빠르게 쇠퇴했습니다. 당나라 때에는 이미 놀이법을 알 수 없게 되었다고 여겨집니다. 사라진 이유는 분명하지 않지만, 바둑 같은 다른 놀이로 인기가 옮겨 갔기 때문이라는 견해가 있습니다.","남은 것은 판과 도구였습니다. 판에는 T・L・V 모양을 조합한 독특한 선이 새겨져 있고, 가는 막대(젓가락)를 던져 나아갈 수를 정했다고 여겨집니다. 같은 무늬는 'TLV 거울'이라 불리는 거울에도 쓰였습니다.","문자 기록에서도 단서가 조금씩 모이고 있습니다. 1993년 장쑤성 인완 한묘에서 판 그림을 이용한 점술 문서가 나왔습니다. 2010년대에 발굴된 해혼후 유하의 무덤에서는 육박과 관련된 죽간이 1000매 넘게 발견되어 연구가 이어지고 있습니다.","대백과의 '육박'은 이런 단서를 바탕으로 한 복원판입니다. 연구자마다 복원 방식이 조금씩 다르고, 진짜 규칙은 아직 완전히 밝혀지지 않았습니다. 새로운 발견이 있으면 놀이법이 바뀔지도 모르는 게임입니다."],"quiz":[["육박이 크게 유행한 것은 중국의 어느 시대?","한","명","청","송"],["육박과 관련된 죽간이 1000매 넘게 발견된 곳은?","해혼후 유하의 무덤","진시황릉","둔황 석굴","자금성"],["육박에서 나아갈 수를 정하려고 던진 것으로 여겨지는 도구는?","가는 막대(젓가락)","20면 주사위","팽이","그림이 그려진 패"]],"kf":["전국시대부터 한나라까지(기원전 5세기~3세기) 중국에서 크게 유행했다","판에는 T·L·V를 조합한 독특한 선, 던지는 것은 가는 막대","한나라가 망하자 급격히 쇠퇴해, 놀이 방법은 지금도 완전히 밝혀지지 않았다"],"more":[{"h":"T·L·V의 판","p":["육박 판은 정사각형으로, 가운데에 네모, 각 변 가운데에 T, 그 둘레에 L, 네 모서리에 V 모양의 선이 새겨져 있습니다. 말은 이 선 위나 사이를 나아갔다고 봅니다.","같은 선은 거울 뒷면 무늬(TLV 거울)와 해시계에도 보입니다. 판을 하늘과 땅, 사방을 나타낸 우주의 그림으로 본 학자도 있어, 육박이 단순한 놀이가 아니었음을 느끼게 합니다."],"cap":["육박 판의 선(TLV 무늬): 가운데 네모, 각 변의 T, 모서리 쪽의 L과 V"]},{"h":"어떻게 놀았나","p":["두 사람이 각각 말 6개를 가지고 가는 대나무 막대를 던져 나아갈 수를 정했다는 것이 많은 학자의 생각입니다. ‘육박’의 ‘육’은 이 막대 6개나 말 6개에서 왔다고 합니다.","말은 나아가면 강한 ‘효(梟)’가 된 듯하며, 기원전 3세기쯤의 『초사』 「초혼」에는 “효가 되어 몰아치며 오백을 외친다”는 구절이 있습니다. 판 가운데 ‘물’에서 ‘물고기’를 잡는 놀이 방법도 기록되어 있습니다."],"cap":["한나라 무덤에 넣은, 육박을 두는 두 사람의 상(메트로폴리탄 미술관)"]},{"h":"무덤에서 나온 도구","p":["후난성 창사의 마왕퇴 한묘 3호묘(기원전 168년경)에서는 칠기 상자에 든 판·말·막대가 한 벌로 나왔습니다. 죽은 이가 저세상에서도 놀 수 있도록 넣은 것입니다.","무덤 벽이나 돌에 새긴 화상석에는 신선들이 산 위에서 육박을 두는 장면이 자주 그려집니다. 육박은 불로장생의 세계와 이어진 특별한 놀이이기도 했습니다."],"cap":["소장품 육박 판. 박물관 소장품 전시실에서 3D로 볼 수 있습니다"]}],"tl":[["기원전 5~3세기(전국시대)","육박 판이 무덤에 들어가기 시작한다"],["기원전 3세기경","『초사』 「초혼」에 육박 두는 모습이 읊어진다"],["기원전 168년경","마왕퇴 한묘 3호묘에 판·말·막대 한 벌이 들어간다"],["기원전 206~기원후 220년(한)","황제부터 서민까지 크게 유행, 화상석과 거울 무늬에도"],["당(7~10세기)","놀이 방법이 잊혔다고 본다"],["1993년","인완 한묘에서 판 그림으로 점치는 문서가 나온다"],["2010년대","해혼후 유하의 무덤에서 육박 죽간이 발견된다"]]},"zeno":{"title":"제논 황제의 불운한 한 수","lead":"1500년 전, 한 황제가 던진 주사위 눈이 시가 되어 지금까지 남아 있습니다.","s":["로마 사람들은 24개의 점이 있는 판에서 주사위를 던져 말을 움직이는 '타불라'를 즐겼습니다. 오늘날 백개먼의 조상입니다. 속임수를 막으려고 주사위를 안에서 굴러떨어지게 하는 '주사위 탑'까지 썼습니다.","서기 480년경, 동로마 황제 제논이 타불라를 두고 있었습니다. 세 개의 주사위 눈은 2・5・6. 규칙대로 움직일 수밖에 없었고, 판 위에는 홀로 선 무방비한 말이 8개나 생기고 말았습니다.","이 판을 기록한 사람은 제논보다 수십 년 뒤인 6세기에 살았던 역사가이자 시인 아가티아스입니다. 그의 짧은 시(에피그램)는 말의 위치까지 자세히 전해, 고대 보드게임의 판세를 알 수 있는 드문 기록이 되었습니다.","19세기에 프랑스 연구자 베크 드 푸키에르가 이 시에서 판세와 규칙을 풀어냈습니다. 말은 한 사람당 15개, 주사위는 3개. 모든 말은 판 밖에서 시작하고, 두 사람 모두 같은 방향으로 나아갑니다.","오늘날의 백개먼과 다른 점은 주사위가 3개라는 것, 처음에 판 위에 말이 없다는 것, 그리고 더블링 큐브가 없다는 것입니다. 황제의 불운 덕분에 우리는 타불라의 모습을 알 수 있습니다."],"quiz":[["제논이 던진 주사위 눈은?","2・5・6","6・6・6","1・1・1","3・4・5"],["이 판을 시로 기록한 사람은?","아가티아스","호메로스","플리니우스","키케로"],["타불라와 오늘날 백개먼의 차이로 옳은 것은?","주사위가 3개","말이 한 사람당 30개","판이 12개의 점","말이 거꾸로 나아간다"]],"kf":["타불라는 24개의 점과 주사위 3개로 하는 백개먼의 조상","480년경 황제 제논의 대국이 판의 모습째 시로 남았다","로마인은 속임수를 막는 ‘다이스 타워’까지 만들었다"],"more":[{"h":"타불라의 판","p":["타불라 판은 지금의 백개먼처럼 24개의 점을 12개씩 두 줄로 놓은 것입니다. 말은 한 사람에 15개로, 처음에는 모두 판 밖에 있다가 주사위 3개의 눈에 따라 판에 들어가 한 바퀴 돌아 밖으로 나갑니다.","백개먼과 크게 다른 점은 두 사람이 같은 방향으로 나아간다는 것입니다. 홀로 선 말은 상대가 그 칸에 멈추면 잡혀 다시 들어가야 합니다. 제논의 판에 8개나 생긴 것이 바로 이 잡히기 쉬운 말이었습니다."],"cap":["타불라 판. 24개의 점을 12개씩 두 줄로 놓고, 양쪽 말이 같은 방향(화살표)으로 나아간다"]},{"h":"속임수를 막는 도구","p":["로마 사람들은 주사위 놀이에 푹 빠져 있었고, 법으로 도박이 금지되어 겨울의 사투르날리아 축제 동안에만 허락되었다고 합니다. 그래도 도박은 그치지 않았고, 손으로 주사위를 조작하는 속임수도 흔했습니다.","그래서 쓰인 것이, 위에서 넣은 주사위가 안의 판에 부딪혀 굴러 나오는 ‘다이스 타워’입니다. 독일의 빌라 터에서 나온 4세기 것에는 “픽트인은 졌고 적은 멸망했다. 안심하고 놀아라”라는 글이 투조되어 있습니다."],"cap":["페트바이스-프로이츠하임의 다이스 타워(4세기). 소장품 전시실에서 3D로 볼 수 있습니다"]},{"h":"황제들과 주사위","p":["제논만이 아닙니다. 역사가 수에토니우스에 따르면 1세기의 황제 클라우디우스는 주사위 놀이를 무척 좋아해 그 기술에 관한 책까지 쓰고, 마차 안에서도 판이 미끄러지지 않게 꾸며 놀았다고 합니다.","로마 유적에서는 36개의 글자를 6자씩 늘어놓은 판도 많이 나옵니다. 글자 하나가 한 칸 구실을 했고, “일어나, 놀 줄 모르면 자리를 비켜라” 같은 놀리는 말이 새겨진 것도 있습니다."],"cap":["타불라와 주사위 놀이는 황제부터 병사까지의 즐거움이었습니다(우연의 도구 전시실에서 정육면체 주사위를 던질 수 있습니다)"]}],"tl":[["1세기","클라우디우스 황제가 주사위 놀이 책을 쓴다"],["4세기","독일의 빌라에서 다이스 타워가 쓰인다"],["480년경","동로마 황제 제논의 불운한 대국"],["6세기","아가티아스가 그 대국을 시로 읊는다"],["10세기경","시가 『그리스 사화집』에 묶여 전해진다"],["1869년","벡 드 푸키에르가 판의 모습과 규칙을 풀어낸다"],["1934년","오스틴이 제논의 대국을 자세히 다시 검증한다"]]},"sugoroku":{"title":"금지된 쌍륙","lead":"천황이 금해도 사람들은 쌍륙을 그만두지 않았습니다. 고대부터 에도 시대까지 일본 반쌍륙의 이야기.","s":["쇼소인에는 쇼무 천황이 아꼈다고 전하는 '목화자단 쌍륙판'이 남아 있습니다. 여기서 말하는 쌍륙은 종이 그림 놀이가 아니라, 판 위에서 흰 말과 검은 말을 움직이는 '반쌍륙'으로 백개먼의 친척입니다.","쌍륙은 일찍부터 도박과 엮였습니다. 《일본서기》에 따르면 689년에 지토 천황이 쌍륙을 금지했습니다.","757년에 시행된 요로 율령에도 승려와 비구니의 쌍륙을 금하는 규정이 있었습니다. 그런데도 금령이 거듭 내려진 것을 보면, 잘 지켜지지 않았던 모양입니다.","헤이안 시대에도 쌍륙은 계속 즐겨져 《마쿠라노소시》와 《겐지 이야기》에도 등장합니다. 시라카와 법황이 뜻대로 되지 않는 것으로 '가모강의 물, 쌍륙의 주사위, 산법사(히에이산의 승병)'를 꼽았다는 이야기는 《헤이케 이야기》에 실려 있습니다.","에도 시대 판화에도 방 안에서 반쌍륙을 즐기는 소녀들이 그려져 있습니다. 하지만 메이지 무렵에는 반쌍륙을 거의 하지 않게 되었고, '스고로쿠'라고 하면 종이 그림 쌍륙을 가리키게 되었습니다."],"quiz":[["쇼소인의 쌍륙판 같은 '반쌍륙'은 오늘날 어느 게임의 친척일까요?","백개먼","쇼기","바둑","트럼프"],["《일본서기》에서 쌍륙을 금지했다고 하는 천황은?","지토 천황","쇼무 천황","간무 천황","메이지 천황"],["시라카와 법황이 뜻대로 되지 않는다고 한 것은 가모강의 물, 승병과 무엇?","쌍륙의 주사위","쇼기의 말","바둑돌","게마리 공"]],"kf":["반스고로쿠는 백개먼의 친척으로, 7세기에는 일본에서 즐겼다","689년 지토 천황을 시작으로, 도박을 이유로 여러 번 금지되었다","메이지 무렵 잊혀, ‘스고로쿠’는 종이 그림 놀이를 가리키게 되었다"],"more":[{"h":"쇼소인의 스고로쿠 판","p":["쇼소인에 전해지는 ‘목화자단 쌍륙국’은 자단 판에 상아와 물들인 나무를 섬세하게 박은 호화로운 판입니다. 좌우에 12개씩, 모두 24개의 칸이 있고 가운데 칸막이에 꽃무늬가 놓여 있습니다.","쇼소인에는 유리와 돌로 만든 스고로쿠 말도 많이 남아 있습니다. 반스고로쿠는 흑백 각 15개의 말과 주사위 2개를 써서, 지금의 백개먼과 아주 비슷합니다. 페르시아의 나르드가 중국을 거쳐 전해졌다고 봅니다."],"cap":["쇼소인의 목화자단 스고로쿠 판. 박물관 소장품 전시실에서 둘 수 있습니다"]},{"h":"반스고로쿠 놀이법","p":["두 사람이 각각 15개의 말을 정해진 자리에 놓고, 주사위 2개의 눈만큼 나아갑니다. 흑과 백은 반대 방향으로 돌고, 자기 말을 모두 마지막 6칸(내지)에 먼저 모은 쪽이 이깁니다.","홀로 선 말은 상대에게 맞아 출발점으로 돌아갑니다. 2개 이상 겹친 칸에는 상대가 들어갈 수 없으므로, 말을 이어 길을 막는 것이 요령입니다. 박물관 소장품 전시실에서 이 방법으로 쇼소인의 판과 대국할 수 있습니다."],"cap":["반스고로쿠 판(모식도). 24개의 칸과, 흑백이 서로 반대로 나아가는 길"]},{"h":"금지와 유행의 되풀이","p":["지토 천황 이후에도 스고로쿠는 여러 번 금지되었습니다. 도박에 빠져 재산을 잃는 사람이 끊이지 않았기 때문입니다. 가마쿠라 막부도 스고로쿠 도박을 금하는 법령을 냈습니다.","한편 스고로쿠는 귀족의 교양이기도 했습니다. 아름다운 판이 혼수에 들어갔고, 에도 시대에는 마키에로 꾸민 호화로운 판도 만들어졌습니다. 도박 도구로 미움받고 보물로 사랑받은 ― 반스고로쿠는 두 얼굴을 가졌습니다."],"cap":["에도 시대 그림에 그려진 반스고로쿠(그려진 게임 전시실)"]}],"tl":[["7세기","반스고로쿠가 중국에서 전해진다"],["689년","지토 천황이 스고로쿠를 금한다(『일본서기』)"],["8세기","목화자단 쌍륙국이 쇼소인에 들어간다"],["757년","요로 율령 시행, 승려의 스고로쿠를 경계한다"],["헤이안 시대","『마쿠라노소시』『겐지 이야기』에 스고로쿠가 나온다"],["12세기","시라카와 법황의 ‘스고로쿠 주사위’ 한탄(『헤이케 이야기』)"],["에도 시대","혼수용 호화로운 판이 만들어진다"],["메이지","반스고로쿠가 거의 사라진다"]]},"queen":{"title":"체스의 퀸은 왜 가장 강해졌을까","lead":"지금 가장 강한 말은, 원래 대각선으로 한 칸밖에 못 가는 신하였습니다.","s":["체스의 조상은 인도에서 페르시아, 아랍으로 전해졌습니다. 페르시아의 서사시 《샤나메(왕서)》에는 인도에서 온 체스의 수수께끼를 현자 부주르그미흐르가 푸는 장면이 있습니다. 그 무렵 판에서 왕 옆에 있던 말은 '페르즈(대신)'였습니다.","페르즈는 대각선으로 한 칸밖에 못 가는 아주 약한 말입니다. 12세기 이란 니샤푸르의 체스 세트에서는 왕보다 작은 옥좌 모양을 하고 있습니다.","체스가 유럽으로 퍼지자 대신은 '여왕'으로 바뀌었습니다. 12세기 루이스섬의 체스 말에도 여왕이 있습니다. 그러나 이름이 바뀌어도 움직임은 여전히 약했습니다.","큰 변화는 15세기 말 스페인에서 일어났습니다. 1475년경 발렌시아에서 쓰인 시 《스카크스 다모르(사랑의 체스)》가 가로・세로・대각선으로 얼마든지 나아가는 지금의 퀸의 움직임을 적은 가장 오래된 기록으로 여겨집니다. 이후 1497년 루세나, 1512년 다미아노의 책을 통해 새 규칙이 유럽 전역에 퍼졌습니다.","퀸이 왜 강해졌는지는 분명하지 않습니다. 승부를 빨리 내고 싶었기 때문이라는 견해도 있고, 이사벨 1세 같은 강한 여왕의 존재가 영향을 주었다는 설도 있습니다. 이 변화로 체스는 지금의 모습에 크게 가까워졌습니다."],"quiz":[["페르시아와 아랍의 체스에서 지금의 퀸 자리에 있던 말은?","페르즈(대신)","코끼리","전차","기사"],["원래 페르즈의 움직임은?","대각선으로 한 칸","직선으로 얼마든지","두 칸 뛰기","움직일 수 없음"],["지금의 퀸 움직임을 적은 가장 오래된 기록으로 여겨지는 시가 쓰인 곳은?","15세기 발렌시아","6세기 인도","12세기 루이스섬","19세기 런던"]],"kf":["여왕의 전신은 페르시아·아랍의 ‘페르즈(대신)’로, 대각선으로 한 칸밖에 못 움직였다","1475년경 스페인에서 지금의 강한 여왕의 움직임이 처음 기록되었다","새 규칙은 인쇄된 책을 통해 수십 년 만에 유럽 전역에 퍼졌다"],"more":[{"h":"약했던 대신","p":["페르즈는 대각선 옆 한 칸만 갈 수 있었습니다. 판의 끝에서 끝까지 한 번에 달리는 지금의 여왕과는 딴판이지요. 그 무렵 체스는 말의 움직임이 느긋해서 한 판에 몇 시간이 걸리는 일도 흔했습니다.","코끼리(지금의 비숍)도 대각선 두 칸째로 뛰는 것뿐이었습니다. 폰이 마지막 줄에 닿으면 ‘승진’했지만, 될 수 있는 것은 이 약한 페르즈뿐이었습니다."],"cap":["페르즈(왼쪽)와 지금의 여왕(오른쪽)이 움직일 수 있는 범위"]},{"h":"‘여왕의 체스’와 ‘미친 체스’","p":["새 여왕이 나타나자 스페인에서는 이 놀이법을 ‘여왕의 체스’, 이탈리아에서는 그 격렬함 때문에 ‘미친 체스’라고 불렀습니다. 비숍도 같은 무렵 대각선으로 얼마든지 갈 수 있게 됩니다.","말이 강해지자 게임은 단숨에 빠르고 격렬해졌습니다. 몇 수 만에 끝나는 함정이나 정해진 초반 수순(정석)을 연구하는 책이 잇따라 나왔고, 체스는 ‘연구하는 놀이’가 되어 갔습니다."],"cap":["리베랄레 다 베로나 《체스 두는 사람들》(1475년경). 마침 새 여왕이 태어나던 무렵의 그림입니다"]},{"h":"왜 여왕이었을까","p":["대신이 왜 여왕으로 바뀌었는지는 분명하지 않습니다. 왕 옆에 선 말을 왕비로 본 것은 자연스러웠는지도 모릅니다. 라틴어에서 ‘페르즈’는 ‘페르시아’가 되었다가 ‘레지나(여왕)’라 불리게 됩니다.","강해진 이유도, 승부를 빨리 내고 싶었다는 생각 외에 카스티야의 이사벨 1세 같은 힘 있는 여왕들의 시대였기 때문이라는 설이 있습니다. 역사가 메릴린 얄롬은 이 변화를 중세 여성의 지위와 연결해 논했습니다."],"cap":["루이스섬 체스 말의 여왕(12세기). 움직임은 아직 약했습니다"]}],"tl":[["6세기경","인도에서 체스의 조상 차투랑가가 생겨난다"],["7~9세기","페르시아·아랍에서 즐기며, 왕 옆은 페르즈"],["10세기경","체스가 유럽에 전해진다"],["12세기","루이스섬 체스 말에 여왕이 나타난다(움직임은 약함)"],["1475년경","발렌시아의 시 『사랑의 체스』에 새 여왕의 움직임"],["1497년","루세나의 체스 책이 스페인에서 인쇄된다"],["1512년","다미아누의 책이 이탈리아에서 나와 새 규칙이 퍼진다"]]},"senet":{"title":"세네트는 왜 저승으로 가는 여행이 되었을까","lead":"고대 이집트에서 3000년 가까이 즐긴 게임은, 이윽고 죽은 이의 영혼이 떠나는 여행을 나타내게 되었습니다.","s":["세네트는 3줄×10칸의 판에서 말을 움직이는 고대 이집트의 게임입니다. 기원전 3100년경 제1왕조의 무덤에서 세네트로 보이는 판의 조각이 나왔습니다. 왕족은 화려한 상자로, 서민은 돌에 새긴 판으로 즐겼습니다.","이름은 '지나감'이라는 뜻입니다. 신왕국 시대(기원전 1550년경부터)에 이르러 세네트는 죽은 이의 영혼이 저승을 지나가는 여행과 이어지게 되었습니다.","《사자의 서》 제17장에는 죽은 이가 보이지 않는 상대와 세네트를 두는 장면이 그려져 있습니다. 람세스 2세의 왕비 네페르타리의 무덤 벽에도 세네트 판 앞에 앉은 왕비의 모습이 있습니다.","투탕카멘의 무덤에서는 적어도 5개의 게임 상자가 나왔습니다. 그중 흑단과 상아로 만든 큰 상자는 앞면이 세네트, 뒷면이 20칸짜리 다른 게임의 판입니다.","그런데 놀이법을 정리해 쓴 기록은 발견되지 않았습니다. 20세기에 제키에, 벨, 켄들(1978년) 등이 판과 그림, 문서 조각을 바탕으로 각자 놀이법을 복원했습니다. 대백과의 세네트도 이런 연구에 바탕을 둔 놀이법 중 하나입니다."],"quiz":[["'세네트'라는 이름의 뜻은?","지나감","왕의 놀이","30개의 집","강 건너기"],["신왕국 시대에 세네트는 무엇과 이어졌을까요?","죽은 이의 영혼이 저승을 지나가는 여행","기우제","전투 작전","수확 점"],["투탕카멘의 무덤에서 나온 게임 상자는 적어도 몇 개?","5개","1개","2개","100개"]],"kf":["3줄×10칸, 30칸 판에서 말을 나아가게 하는, 세계에서 가장 오래된 보드게임 가운데 하나","이름은 ‘지나감’. 신왕국 시대에는 영혼이 저승을 지나는 여행과 겹쳐졌다","놀이 방법의 기록은 남지 않았고, 지금의 규칙은 20세기 학자들의 복원"],"more":[{"h":"30칸 판과 특별한 칸","p":["세네트 판은 10칸씩 3줄, 모두 30칸입니다. 말은 첫 줄을 왼쪽에서 오른쪽으로, 둘째 줄을 오른쪽에서 왼쪽으로, 셋째 줄을 다시 왼쪽에서 오른쪽으로 S자를 그리며 나아갔다고 봅니다.","마지막 5칸에는 특별한 표시가 그려지는 일이 많았습니다. 26번째는 ‘아름다운 집’, 27번째는 ‘물’ 칸으로, 물에 빠진 말은 되돌아간다는 복원이 일반적입니다. 28~30번째에는 숫자나 저승의 신들이 그려졌습니다."],"cap":["세네트 판. 말은 S자로 나아가고, 마지막 5칸(26~30)에는 특별한 표시가 있다"]},{"h":"던지는 막대로 나아간다","p":["주사위 대신 쓴 것은 한쪽이 평평하고 한쪽이 둥근 막대 4개나 동물의 거골이었습니다. 평평한 면이 위로 온 개수만큼 나아가고, 0개면 5칸 간다고 보는 학자가 많습니다.","이 세는 법은 멀리 떨어진 한국 윷놀이의 윷과 똑같습니다. 박물관 ‘우연의 도구’ 전시실에서 막대를 던져 1~5가 나오는 정도의 차이를 확인해 보세요."],"cap":["이집트의 던지는 막대(우연의 도구 전시실에서 던질 수 있습니다)"]},{"h":"투탕카멘의 게임 상자","p":["1922년 하워드 카터가 연 투탕카멘의 무덤에는 적어도 5개의 게임 상자가 들어 있었습니다. 가장 큰 상자는 흑단과 상아로 만들어졌고, 서랍에 말과 막대를 넣을 수 있습니다.","앞뒤가 모두 판인 상자가 이 시대에 흔히 만들어졌습니다. 한쪽은 세네트, 다른 쪽은 우르 왕실 게임과 같은 20칸 판입니다. 왕이 저승에서도 두 게임을 다 할 수 있기를 바랐겠지요."],"cap":["투탕카멘의 세네트 상자(소장품 전시실에서 3D로 보고 둘 수 있습니다)"]}],"tl":[["기원전 3100년경","제1왕조 무덤에서 세네트로 보이는 판 조각"],["기원전 2600년경","고왕국 무덤 벽화에 세네트를 두는 사람들"],["기원전 1550년경~","신왕국 시대. 세네트가 저승 여행과 이어진다"],["기원전 1323년경","투탕카멘 무덤에 게임 상자 5개가 들어간다"],["기원전 1250년경","네페르타리 무덤 벽에 세네트 앞의 왕비가 그려진다"],["1922년","카터가 투탕카멘 무덤을 연다"],["1978년","켄들이 놀이 방법의 복원을 발표한다"]]},"lewis":{"title":"모래 속에서 나타난 체스 말","lead":"1831년 스코틀랜드의 섬에서 발견된 중세의 말. 그리고 같은 공방의 것으로 보이는 말이 188년 뒤 서랍 속에서 나타났습니다.","s":["1831년, 스코틀랜드 북서쪽의 루이스섬에서 주로 바다코끼리 엄니로 조각한 말이 한꺼번에 발견되었습니다. 체스 말 78개, 보드게임용 원반 14개, 버클 1개, 모두 93점입니다.","발견된 장소와 경위는 분명하지 않습니다. 섬 서쪽의 위그만이라고들 하지만 다른 곳이라는 설도 있습니다. 누가, 왜 그곳에 묻었는지도 알 수 없습니다.","말들은 12세기 후반쯤 노르웨이 트론헤임 주변에서 만들어졌다고 여겨집니다. 왕, 생각에 잠긴 여왕, 주교, 작은 말을 탄 기사, 그리고 방패 가장자리를 깨무는 성병. 북유럽 사가에 나오는 전사 '베르세르크'를 나타낸 것으로 보입니다.","지금은 대영박물관에 82점, 스코틀랜드 국립박물관에 11점이 나뉘어 있습니다. 완전한 세트를 이루려면 말이 몇 개 모자란다고 알려져 왔습니다.","2019년, 에든버러의 골동품상이 1964년에 단 5파운드에 사서 가족이 서랍에 넣어 두었던 성병이 루이스섬 말의 공방 것으로 밝혀졌습니다. 소더비 경매에서 73만 5000파운드에 낙찰되었습니다."],"quiz":[["루이스섬에서 말이 발견된 해는?","1831년","1066년","1931년","1700년"],["말의 주된 재료는?","바다코끼리 엄니","대리석","금","유리"],["2019년에 낙찰된 성병은 몇 년에 5파운드에 팔렸을까요?","1964년","1831년","1990년","2018년"]],"kf":["1831년 스코틀랜드 루이스섬에서 발견된 말과 원반 93점","12세기 후반 노르웨이에서, 주로 바다코끼리 엄니로 깎았다","지금은 대영박물관과 스코틀랜드 국립박물관에 나뉘어 있다"],"more":[{"h":"78개 말의 면면","p":["체스 말 78개는 왕 8, 여왕 8, 주교 16, 기사 15, 성 지기 12, 폰 19. 적어도 4벌이 섞여 있었다고 봅니다.","주교는 주교관을 쓴 모습입니다. 체스의 ‘코끼리’가 ‘주교’로 바뀐 것은 유럽에서였고, 루이스섬의 말은 그 가장 이른 예 가운데 하나입니다. 성 지기 몇은 방패를 물고 있는데, 싸움 전에 광란에 빠지는 전사 ‘베르세르크’를 나타낸다고 합니다."],"cap":["루이스섬 체스 말(소장품 전시실에서 3D로 볼 수 있습니다)","체스 말 78개의 구성"]},{"h":"바다코끼리 엄니와 북쪽 바다","p":["말 대부분은 바다코끼리 엄니, 몇 개는 고래 이빨로 만들었습니다. 바다코끼리 엄니는 그린란드와 노르웨이 북부에서 실어 오던 북쪽 바다의 보물이었습니다.","그 무렵 루이스섬은 노르웨이 왕이 다스리는 섬들의 일부였고, 1266년 퍼스 조약으로 스코틀랜드에 넘어갑니다. 트론헤임 대성당 근처에서도 같은 솜씨의 말 조각이 나와, 말의 고향을 짐작하게 합니다."],"cap":[]},{"h":"발견의 전설과 지금의 인기","p":["누가 찾았는지에 대해서는, 모래밭에서 소가 파냈다, 마을 사람 맬컴 매클라우드가 찾았다 등 여러 이야기가 전해집니다. 발견자는 곧 말을 팔았고, 에든버러를 거쳐 대영박물관이 대부분을 사들였습니다.","시무룩하고 익살스러운 얼굴의 말은 지금도 큰 인기여서, 복제품이 세계 곳곳에서 팔립니다. 영화 『해리 포터와 마법사의 돌』(2001)의 마법사 체스에도 루이스섬 말을 본뜬 말이 나왔습니다."],"cap":[]}],"tl":[["12세기 후반","노르웨이(트론헤임 일대)에서 말이 만들어진다"],["1266년","퍼스 조약으로 루이스섬 등이 스코틀랜드령이 된다"],["1831년","루이스섬에서 93점이 한꺼번에 발견된다"],["1831~32년","대영박물관이 82점을 사들인다"],["1888년","스코틀랜드의 박물관이 11점을 얻는다"],["2001년","영화 『해리 포터』의 마법사 체스에 나온다"],["2019년","5파운드에 산 성 지기가 73만 5000파운드에 낙찰된다"]]},"tafl":{"title":"왕을 탈출시키는 게임과 잘못된 번역","lead":"바이킹 보드게임의 놀이법은 18세기 라플란드 여행 일기에서 풀어냈습니다.","s":["바이킹 시대의 북유럽에서는 '타플'이라는 보드게임을 즐겼습니다. 판 한가운데의 왕과 소수의 호위병이 둘레를 에워싼 많은 군대와 싸우는, 병력이 서로 다른 두 군대의 게임입니다.","1932년 아일랜드 밸린데리에서 발견된 10세기의 나무판에는 7×7개의 구멍이 있고, 가운데와 네 귀퉁이 구멍에 표시가 있습니다. 왕이 서는 가운데와 왕이 달아나는 귀퉁이의 표시로 여겨집니다.","하지만 중세의 놀이법을 적은 기록은 거의 남아 있지 않습니다. 큰 실마리가 된 것은 1732년 25세의 박물학자 린네가 라플란드(스웨덴 북부)를 여행하며 쓴 일기입니다. 린네는 그곳에서 사미족이 즐기던 '타블루트'의 놀이법을 적어 두었습니다.","이 일기는 1811년 영어로 번역되어 출판되었는데, 번역에 잘못이 있었습니다. 그 번역을 바탕으로 한 머리의 복원(1913년)이 오랫동안 타플의 표준 규칙이 되고 말았습니다.","그 뒤 플레이어와 연구자들이 이 잘못을 바로잡아, 지금은 여러 판의 규칙이 쓰이고 있습니다. 대백과의 타플도 그중 하나입니다."],"quiz":[["린네가 라플란드에서 적어 둔 게임의 이름은?","타블루트","세네트","만칼라","체스"],["지키는 쪽이 귀퉁이로 탈출시키려는 말은?","왕","여왕","깃발","배"],["잘못이 있는 영어 번역이 출판된 해는?","1811년","1732년","1932년","1066년"]],"kf":["가운데의 왕과 소수의 수비군이 더 많은 공격군에게 둘러싸여 싸우는, 병력이 다른 두 군대의 게임","바이킹 시대 북유럽에서 즐겼고, 판은 7×7부터 19×19까지 크기가 다양하다","놀이법의 단서는 1732년 린네의 여행 일기와 오류가 있는 그 영어 번역"],"more":[{"h":"밸린데리 판","p":["아일랜드 중부의 호수 위 주거지(크래녹) 유적에서 나온 밸린데리 판은 주목 나무로 만들어졌습니다. 7×7, 49개의 구멍에 말 밑의 돌기를 꽂아 놀았던 것으로 보입니다.","판 가장자리에는 사람 머리 모양의 손잡이가 새겨져 있어, 들고 다닐 수 있는 판이었던 듯합니다. 아일랜드에는 ‘브란두브(검은 까마귀)’라는 7×7 타플의 이름이 전해지는데, 이 판에서 놀았을지도 모릅니다."],"cap":["밸린데리 판(7×7)에 아일랜드 ‘브란두브’의 처음 배치를 놓은 모습. 금색 고리는 가운데와 네 귀퉁이 표시"]},{"h":"린네의 타블루트","p":["린네가 기록한 타블루트는 9×9 판을 씁니다. 가운데 왕좌에 왕이 서고, 수비 쪽 ‘스웨덴인’ 8명과 공격 쪽 ‘모스크바인’ 16명이 싸웁니다.","모든 말은 장기의 차처럼 곧게 몇 칸이든 움직이고, 적의 말 둘 사이에 앞뒤나 좌우로 끼이면 잡힙니다. 왕이 판 가장자리에 닿으면 수비 쪽, 왕을 사방에서 에워싸면 공격 쪽이 이깁니다. 린네는 라틴어와 스웨덴어를 섞어 썼고, 영어 번역에서는 몇 가지가 원문과 달라졌습니다."],"cap":["린네가 기록한 타블루트(9×9). 가운데 왕좌에 왕, 수비 8, 공격 16. 왕이 초록색 가장자리 칸에 닿으면 수비 쪽 승리"]},{"h":"커지는 판, 사라져 가는 게임","p":["타플 판은 7×7 말고도 9×9, 웨일스의 11×11, 그리고 19×19까지 있습니다. 가장 큰 ‘알레아 에반젤리’는 12세기 필사본에 그려져 있고, 10세기 잉글랜드 애설스탠 왕의 궁정에서 전해졌다고 적혀 있습니다.","12~13세기에 체스가 북유럽에 퍼지자 타플은 점점 사라졌습니다. 먼 라플란드에만 남은 타블루트를 린네가 우연히 기록한 것입니다. 지금은 11×11 판으로 겨루는 국제 대회도 열리며 다시 즐기는 사람이 늘고 있습니다."],"cap":["루이스섬 발견물(12세기). 체스 말과 함께 판 게임용 원반 14개가 나왔습니다"]}],"tl":[["10세기","아일랜드에서 밸린데리 판이 만들어짐"],["924~939년","애설스탠 왕의 궁정에서 알레아 에반젤리를 즐겼다고 전해짐"],["12세기","알레아 에반젤리 그림이 필사본에 그려짐"],["12~13세기","체스가 북유럽에 퍼지고 타플이 사라져 감"],["1732년","린네가 라플란드에서 타블루트를 기록"],["1811년","린네 일기의 영어 번역 『라케시스 라포니카』 출간"],["1913년","머리가 『체스의 역사』에서 타플을 복원"],["1932년","밸린데리 판 발견"]]},"goose":{"title":"왕에게 바친 거위 게임","lead":"주사위를 굴려 나선형 63칸을 나아가는 게임은 왕에게 선물되었고, 이윽고 유럽 전역에서 즐기게 되었습니다.","s":["거위 게임은 주사위를 굴려 나선으로 늘어선 63칸을 지나 가운데 결승점까지 가는 경주 게임입니다. 거위가 그려진 칸에 멈추면 같은 눈의 수만큼 한 번 더 나아갑니다. 우물, 감옥, 죽음의 칸에서는 발이 묶이거나 출발점으로 돌아갑니다.","16세기 이탈리아에서 생겨났다고 여겨집니다. 토스카나 대공 프란체스코 1세 데 메디치가 1574년에서 1587년 사이에 스페인 왕 펠리페 2세에게 이 게임을 선물했다고 전해집니다.","영국에는 1597년 런던의 인쇄업자 존 울프가 '새롭고 아주 즐거운 거위 게임'을 출판물로 등록한 기록이 있습니다. 17~18세기에는 유럽 전역에서 크게 유행했습니다.","판은 종이에 인쇄되어 퍼졌고, 그림을 바꾼 판이 셀 수 없이 만들어졌습니다. 지리를 배우는 판, 이야기와 우화의 판, 상품 광고 판까지 있습니다. 뒷날 많은 경주 게임의 바탕이 되었다고 여겨집니다.","메트로폴리탄 미술관의 양면 판은 한쪽이 거위 게임, 뒷면이 체스입니다. 16세기 후반 인도 구자라트의 장인이 만든 것으로 보이며, 현존하는 가장 오래된 거위 게임 판일지도 모릅니다."],"quiz":[["거위 게임의 칸은 몇 개?","63","64","100","30"],["이 게임을 스페인 왕에게 선물했다고 전해지는 사람은?","프란체스코 1세 데 메디치","나폴레옹","엘리자베스 1세","루이 14세"],["거위 칸에 멈추면?","같은 눈의 수만큼 한 번 더 나아간다","출발점으로 돌아간다","한 번 쉰다","상대와 자리를 바꾼다"]],"kf":["주사위를 굴려 63칸의 나선을 따라 가운데 결승점까지 가는 경주 게임","16세기 이탈리아에서 태어나 메디치 가문이 스페인 왕에게 선물했다고 전해진다","종이에 인쇄되어 퍼졌고, 주제를 바꾼 판이 셀 수 없이 만들어졌다"],"more":[{"h":"나선의 63칸","p":["잘 알려진 판에는 거위 칸 말고도 특별한 칸이 몇 개 있습니다. 6번 ‘다리’에 서면 12까지 나아가고, 19번 ‘여관’에서는 한 번 쉬며, 31번 ‘우물’과 52번 ‘감옥’에서는 다른 사람이 와서 구해 줄 때까지 움직일 수 없습니다.","42번 ‘미로’에 서면 30으로 돌아가고, 58번 ‘죽음’에 서면 처음부터 다시 시작합니다. 결승점 63에는 꼭 맞는 눈으로 멈춰야 하고, 넘친 만큼은 되돌아갑니다. 마지막 한 걸음이 가장 어려운 게임입니다."],"cap":["63칸을 바깥에서 안쪽으로 나선형으로 늘어놓은 그림. 초록은 거위, 파랑은 다리, 노랑은 발묶임(여관·우물·감옥), 빨강은 후퇴(미로·죽음), 금색은 결승점"]},{"h":"9의 수수께끼","p":["거위 칸은 5, 9, 14, 18……처럼 4칸과 5칸 간격으로 번갈아 놓여 있습니다. 9의 배수 칸에는 늘 거위가 있으므로, 9가 나와 9에 서면 18, 27……로 계속 뛰어 곧장 63에 닿아 버립니다.","그래서 주사위 두 개로 하는 판에는 “처음에 6과 3이 나오면 26으로, 5와 4가 나오면 53으로”라는 특별한 규칙이 있습니다. 63은 7×9로, 당시 일생에서 가장 위험한 해로 여겨진 63세와 겹쳐 보았다고도 합니다."],"cap":["거위 칸은 4칸·5칸 걸러 번갈아 있어서 9의 배수에는 늘 거위가 있다. 처음에 9가 나오면 거위에서 거위로 뛰어 단숨에 63으로"]},{"h":"인쇄로 퍼지다","p":["판은 동판과 목판으로 찍혀 싸게 살 수 있게 되었습니다. 프랑스에서는 ‘죄 드 루아’, 스페인에서는 ‘후에고 데 라 오카’라 불렸고, 스페인에는 “거위에서 거위로”라는 관용구가 지금도 남아 있습니다.","그림을 바꾼 판도 잇달아 만들어졌습니다. 지리와 역사를 배우는 판, 프랑스 혁명이나 나폴레옹을 소재로 한 판, 상품 광고 판까지 있습니다. 같은 63칸 위에 시대마다의 관심사가 그려져 온 것입니다."],"cap":[]}],"tl":[["16세기","이탈리아에서 태어난 것으로 여겨짐"],["1574~87년","메디치가의 프란체스코 1세가 스페인 왕 펠리페 2세에게 선물했다고 전해짐"],["16세기 후반","인도 구자라트에서 앞면은 거위, 뒷면은 체스인 양면 판이 만들어짐"],["1597년","런던의 존 울프가 출판물로 등록"],["17~18세기","유럽 전역에서 크게 유행하고 주제를 바꾼 판이 늘어남"],["1790년대","프랑스 혁명을 소재로 한 판이 만들어짐"],["19세기","어린이 놀이로 여러 나라에서 대량 인쇄됨"]]},"shogi":{"title":"쇼기의 '모치고마'는 언제 생겼을까","lead":"잡은 말을 내 말로 다시 놓을 수 있는 것은 체스 가족 중 쇼기뿐입니다. 이 규칙은 언제, 왜 생겼을까요?","s":["인도에서 생긴 체스의 조상은 동서로 퍼져, 일본에서는 쇼기가 되었습니다. 일본에서 가장 오래된 쇼기 말은 1990년대 초 나라 고후쿠지 옛 경내 발굴에서 나온 16개입니다. 함께 '덴키 6년(1058)'이라고 적힌 나무 패가 나와, 말도 같은 무렵의 것으로 여겨집니다.","그 무렵의 문헌에도 쇼기가 나옵니다. 11세기 중엽의 《신사루가쿠키》에 쇼기의 이름이 있고, 헤이안 시대 말의 기록을 모은 《니추레키》에는 옥장·금장·은장·계마·향차·보병을 쓰는 '헤이안 쇼기'가 적혀 있습니다.","가마쿠라·무로마치 시대에는 말의 수를 늘린 큰 쇼기가 여럿 생겼습니다. 오늘날 쇼기의 바탕이 된 '소쇼기'에는 비차·각행 외에 지금은 없는 '취상'이라는 말도 있었습니다.","모치고마 규칙은 16세기 무렵 생겼다고 여겨집니다. 고나라 천황이 소쇼기에서 취상을 없애게 했다는 이야기가 전해지며, 모치고마도 그 무렵 시작된 것으로 봅니다.","왜 모치고마가 생겼는지는 분명하지 않습니다. 양쪽 말의 색이 같고 방향으로만 구별하기 때문에, 잡은 말을 그대로 쓰기 쉬웠다는 견해가 있습니다. 모치고마 덕분에 쇼기는 끝까지 말이 줄지 않고, 무승부가 드문 게임이 되었습니다."],"quiz":[["고후쿠지 말과 함께 나온 패에 적힌 해는?","덴키 6년(1058)","다이호 원년(701)","덴쇼 10년(1582)","메이지 원년(1868)"],["모치고마 규칙이 생긴 것으로 여겨지는 때는?","16세기 무렵","8세기 무렵","19세기 무렵","20세기 이후"],["잡은 말을 다시 쓰기 쉬웠던 이유로 꼽히는 것은?","양쪽 말의 색이 같고 방향으로 구별한다","말이 금으로 만들어졌다","판의 칸이 적었다","주사위로 말을 골랐다"]],"kf":["인도에서 태어난 체스의 친척이 일본에서 자라난, 9×9 판의 게임","가장 오래된 말은 덴키 6년(1058)의 패와 함께 고후쿠지 옛 경내에서 나왔다","잡은 말을 자기 말로 놓을 수 있는 ‘지고마’는 16세기 무렵 생겼다고 여겨진다"],"more":[{"h":"같은 색의 말, 방향으로 구별","p":["체스 말은 흰색과 검은색으로 칠해져 있지만, 쇼기 말은 적과 아군 모두 같은 나무 색이고, 오각형의 뾰족한 끝이 어느 쪽을 향하는지로 구별합니다. 잡은 말을 방향만 바꿔 다시 놓을 수 있는 것은 이 모양 덕분입니다.","말에는 이름이 적혀 있고, 적진에 들어가면 뒤집어 ‘승격’할 수 있습니다. 보는 뒷면의 ‘と’가 되어 금장과 같이 움직입니다. 말이 입체 인형이 아니라 글자를 쓴 판인 것은 중국의 샹치, 한국의 장기와 같은 동아시아 장기 가족의 특징입니다."],"cap":["쇼기 말은 양쪽 모두 같은 색. 뾰족한 끝의 방향으로 구별한다. 오른쪽은 뒤집어 ‘승격’한 보(도킨)"]},{"h":"큰 쇼기의 시대","p":["가마쿠라·무로마치 시대부터 에도 시대에 걸쳐, 말의 종류와 수를 계속 늘린 큰 쇼기가 만들어졌습니다. 12×12의 주쇼기는 에도 시대까지 널리 즐겼고, 지금도 애호가가 있습니다.","기록에는 15×15의 다이쇼기, 25×25의 타이쇼기, 그리고 36×36 판에 804개의 말을 놓는 다이쿄쿠쇼기까지 남아 있습니다. 하지만 평소에 즐긴 것은 9×9의 쇼쇼기였고, 지고마 규칙을 얻어 지금의 쇼기가 되었습니다."],"cap":["판 크기 비교(왼쪽 아래를 맞춰 그림). 9×9가 지금의 쇼기(말 40개), 12×12가 주쇼기(92개), 15×15가 다이쇼기(130개), 25×25가 타이쇼기(354개), 36×36이 다이쿄쿠쇼기(804개)"]},{"h":"에도의 쇼기","p":["에도 시대에는 막부에서 녹봉을 받는 쇼기 가문이 생겼고, 오하시 소케이가 그 초대로 꼽힙니다. 해마다 쇼군 앞에서 두는 ‘오시로 쇼기’는 뒷날 11월 17일에 열기로 정해졌고, 지금의 ‘쇼기의 날’은 이 날에서 왔습니다.","쇼기는 서민의 즐거움이기도 했습니다. 하루노부의 판화에는 모기장 옆에서 쇼기를 두는 젊은 남녀가 그려져 있습니다. 이토 간주의 『쇼기 즈코』(1755년)처럼 예술품 같은 박보 쇼기 작품집도 나왔습니다."],"cap":["스즈키 하루노부의 니시키에(1767~69년경). 모기장 옆에서 쇼기를 두는 젊은 남녀"]}],"tl":[["1058년","고후쿠지 옛 경내의 말(덴키 6년의 패와 함께 출토)"],["11세기 중엽","『신사루가쿠키』에 쇼기의 이름이 나옴"],["가마쿠라 시대 초","『니추레키』에 헤이안 쇼기의 말이 적힘"],["16세기 무렵","지고마 규칙이 생긴 것으로 여겨짐"],["1612년","오하시 소케이 등이 막부에서 녹봉을 받았다고 전해짐"],["1716년","오시로 쇼기를 11월 17일에 열기로 정함"],["1755년","이토 간주 『쇼기 즈코』"],["1975년","11월 17일이 ‘쇼기의 날’이 됨"]]},"pachisi":{"title":"파치시는 어떻게 루도가 되었을까","lead":"인도 궁정에서 즐기던 십자 모양 판의 게임은 이름을 바꾸어 세계 곳곳의 아이 방에 닿았습니다.","s":["인도에는 십자 모양 판 둘레로 네 사람이 말을 움직이는 차우파르와 파치시라는 게임이 있습니다. 차우파르는 길쭉한 주사위(파사)를 던지고, 파치시는 개오지 조개를 던져 나아갈 수를 정합니다. '파치시'는 '25'라는 뜻으로, 조개를 던져 나오는 가장 큰 수에서 왔습니다.","신화 속에서도 즐겼습니다. 17세기 말의 그림에는 시바 신과 아내 파르바티가 호랑이 가죽 위에서 차우파르 판을 둘러싼 모습이 있습니다.","무굴 제국 아크바르 황제(16세기)의 도성 파테푸르 시크리에는 바닥에 큰 십자 모양 판이 그려진 안뜰이 남아 있습니다. 아크바르는 색색의 옷을 입은 사람을 말로 삼아 놀았다고 전해집니다.","19세기에 이 게임은 바다를 건넜습니다. 미국에서는 '파치지'라는 이름으로 팔려 1874년에 상표가 되었습니다. 영국에서는 1890년대에 '루도'(라틴어로 '나는 논다')라는 이름으로 팔려 가족 게임으로 자리 잡았습니다.","루도는 주사위 하나에 6이 나와야 말을 낼 수 있는 등 규칙이 간단합니다. 스페인의 '파르치스', 독일의 '화내지 마' 등 이름을 바꾼 친척이 세계 곳곳에 있습니다."],"quiz":[["'파치시'라는 이름의 뜻은?","25","왕의 길","십자","개오지 조개"],["큰 십자 모양 판의 안뜰이 남아 있는 아크바르의 도성은?","파테푸르 시크리","델리의 쿠트브 미나르","타지마할","엘로라"],["'루도'는 라틴어로 무슨 뜻?","나는 논다","나는 이긴다","나는 달린다","나는 던진다"]],"kf":["인도의 십자 모양 판에서 네 사람이 둘씩 편을 짜 말을 한 바퀴 돌리는 경주 게임","이름은 ‘25’라는 뜻. 개오지 조개를 던져 나오는 가장 큰 수에서 왔다","19세기에 바다를 건너 파치지, 루도 등 이름을 바꿔 세계로 퍼졌다"],"more":[{"h":"십자 판과 길","p":["파치시 판은 가운데의 ‘차르코니’에서 팔 네 개가 뻗은 십자 모양입니다. 팔은 3줄×8칸으로, 칸은 모두 96개입니다. 판은 천에 수를 놓아 만드는 일이 많아, 쓰지 않을 때는 둘둘 말아 둘 수 있었습니다.","말은 중앙에서 나와 자기 팔의 가운데 줄을 내려가고, 판 둘레를 시계 반대 방향으로 한 바퀴 돈 뒤, 다시 가운데 줄을 올라 중앙으로 돌아옵니다. 마주 앉은 두 사람이 한편이며, 둘 다 말 네 개를 모두 돌려보내면 이깁니다."],"cap":["십자 모양 판(팔마다 3줄×8칸). 파란 선은 한 사람의 말이 가는 길: 자기 팔의 가운데 줄을 내려가 시계 반대 방향으로 한 바퀴 돌고, 가운데 줄을 올라 중앙으로 돌아온다"]},{"h":"개오지 조개 세는 법","p":["파치시에서는 개오지 조개 6개를 던져, 입이 위를 향한 개수로 나아갈 칸 수를 정합니다. 2~6개면 그 수만큼 가지만, 1개면 10칸, 하나도 위를 향하지 않으면 25칸을 갑니다.","25는 64번에 1번밖에 나오지 않는 가장 드물고 큰 수로, 이것이 게임의 이름이 되었습니다. 6·10·25가 나오면 한 번 더 던집니다. 한편 차우파르는 1·2·5·6이 새겨진 길쭉한 막대 주사위 3개를 굴려 놉니다."],"cap":["조개 6개 중 입이 위를 향한 개수(윗줄)와 그때 나아가는 칸 수(아랫줄). 막대 높이는 조개마다 앞뒤가 같은 확률로 나온다고 할 때의 나오기 쉬움"]},{"h":"이름을 바꿔 세계로","p":["인도에 살던 영국인을 통해 이 게임은 19세기에 유럽과 미국으로 건너갔습니다. 미국에서는 ‘파치지’라는 상표가 되었고, 영국에서는 1896년에 ‘루도’가 특허를 받았습니다. 조개 대신 정육면체 주사위 하나를 쓰는 간단한 규칙이 되었습니다.","독일에서는 1914년에 ‘멘슈 에르게레 디히 니히트(화내지 마)’가 나왔고, 스페인에서는 ‘파르치스’로 사랑받습니다. 나라마다 이름과 규칙이 조금씩 달라도, 십자 판을 한 바퀴 돌아 집으로 돌아온다는 뼈대는 그대로입니다."],"cap":[]}],"tl":[["16세기","아크바르의 파테푸르 시크리에 십자 판이 그려진 안뜰이 만들어짐"],["17~18세기","인도 세밀화에 차우파르를 둘러싼 사람들이 자주 그려짐"],["1694~95년","데비다사가 차우파르를 두는 시바와 파르바티를 그림"],["1874년","미국에서 ‘파치지’가 상표가 됨"],["1896년","영국에서 ‘루도’가 특허를 받음"],["1914년","독일에서 ‘멘슈 에르게레 디히 니히트’ 발매"]]},"go":{"title":"1300년 전 바둑판이 말해 주는 것","lead":"쇼소인에 전하는 바둑판에는 지금과 같은 19줄과, 지금과 다른 17개의 꽃 표시가 있습니다.","s":["바둑은 고대 중국에서 생겼습니다. 전설에서는 성왕 요가 아들을 가르치려고 만들었다고 합니다. 기원전의 책 《맹자》에는 바둑 명인 '혁추'의 이름이 나옵니다.","바둑판의 크기는 시대에 따라 바뀌어 왔다고 여겨집니다. 이른 시기에는 17줄 판도 쓰였고, 뒤에 지금과 같은 19줄 판이 퍼졌습니다.","바둑이 일본에 전해진 때는 분명하지 않지만, 나라 시대에는 이미 즐기고 있었습니다. 승려와 비구니의 규칙을 정한 승니령은 음악과 노름을 금하면서도 바둑과 거문고만은 허락했습니다. 쌍륙과는 아주 다른 대접이었습니다.","쇼소인의 '목화자단 바둑판'은 쇼무 천황과 인연 있는 물건으로 전해 온 바둑판입니다. 판은 지금과 같은 19줄이지만, 화점 대신 꽃 모양 표시가 17곳에 있습니다(지금 바둑판의 화점은 9개). 양쪽 서랍은 한쪽을 당기면 다른 쪽도 나오는 장치입니다. 쇼소인에는 빨강과 감색으로 물들인 상아에 새 무늬를 새긴 바둑돌도 전합니다.","헤이안 시대의 《겐지 이야기》에는 바둑을 두는 장면이 그려집니다. 에도 시대에는 혼인보가 등의 가문이 막부를 섬기며, 바둑은 전문 기사가 솜씨를 겨루는 예능이 되었습니다."],"quiz":[["쇼소인 바둑판은 몇 줄?","19줄","17줄","13줄","9줄"],["승니령이 승려와 비구니에게 허락한 놀이는?","바둑과 거문고","쌍륙","노름","게마리"],["쇼소인 바둑판에서 화점 대신 있는 꽃 표시는 몇 개?","17","9","4","25"]],"kf":["흑과 백의 돌을 줄이 만나는 점에 놓고, 둘러싼 집의 넓이를 겨루는 고대 중국 태생의 게임","판은 17줄 시대를 거쳐 19줄로. 쇼소인에는 8세기의 19줄 바둑판이 남아 있다","에도 시대에는 가문이 막부를 섬겼고, 21세기에는 AI가 인간 최고수를 이겼다"],"more":[{"h":"둘러싸서 잡고, 집을 넓힌다","p":["바둑은 흑과 백이 번갈아 판의 줄이 만나는 점에 돌을 놓습니다. 한 번 놓은 돌은 움직이지 않습니다. 돌(또는 돌 무리) 옆의 빈 점이 모두 상대 돌로 막히면, 그 돌은 잡혀서 판에서 들어냅니다.","마지막에 자기 돌로 둘러싼 집과 잡은 돌을 합쳐 많은 쪽이 이깁니다. 규칙은 몇 개 안 되지만 판이 넓어서, 19줄 판에서 나올 수 있는 국면의 수는 10의 170제곱 정도로 계산되었습니다."],"cap":["돌을 잡는 법. 왼쪽: 흑돌 둘레의 빈 점(빨강)은 4개. 가운데: 백에게 세 방향을 막혀 1개 남음. 오른쪽: 마지막 하나도 막혀 흑돌이 잡힘"]},{"h":"17줄에서 19줄로","p":["중국 허베이성 왕두의 후한 시대 무덤에서 17줄 돌 바둑판이 나왔습니다. 한편 6세기 무렵의 것으로 여겨지는 둔황의 『기경』에는 361개의 교점, 즉 19줄 판이 적혀 있습니다. 그 사이에 판이 커진 것으로 보입니다.","쇼소인의 바둑판은 19줄이지만, 지금의 화점 9개와 달리 17곳에 꽃 표시가 있습니다. 교점이 289에서 361로 늘어난 것만으로 게임은 훨씬 깊어졌습니다."],"cap":["17줄과 19줄 판의 교점 수 비교. 지금 19줄 판의 검은 점 9개는 ‘화점’"]},{"h":"신선의 바둑, 가문의 바둑","p":["중국에는 산에서 신선의 바둑을 구경하던 나무꾼이 정신을 차려 보니 도끼 자루가 썩을 만큼 세월이 흘러 있었다는 ‘난가’ 전설이 있습니다. 바둑은 신선의 놀이로 접시나 그림에 자주 그려졌습니다.","일본 에도 시대에는 혼인보가 등의 가문이 막부에서 녹봉을 받아 바둑을 예능으로 갈고닦았습니다. 1938년 혼인보 슈사이의 은퇴 대국은 가와바타 야스나리의 소설 『명인』이 되었습니다. 2016년에는 AI 알파고가 세계 최고수 이세돌에게 4승 1패로 이겨 세계를 놀라게 했습니다."],"cap":["바둑 두는 신선을 새긴 칠기 접시(명 선덕 연간, 1425~36년)"]}],"tl":[["기원전 4세기 무렵","『맹자』에 바둑 명수 혁추의 이름이 나옴"],["후한 시대","왕두의 무덤에 17줄 돌 바둑판이 묻힘"],["6세기 무렵","둔황 『기경』에 19줄·361개 교점이 적힘"],["8세기","쇼소인의 ‘목화자단 바둑판’"],["1612년","혼인보 산사 등이 막부에서 녹봉을 받았다고 전해짐"],["1938년","혼인보 슈사이의 은퇴 대국, 뒷날 가와바타의 『명인』으로"],["2016년","알파고가 이세돌에게 4승 1패"]]},"draughts":{"title":"체커는 어떻게 생겨났을까","lead":"아라비아의 판 게임, 체스판, 그리고 체스의 여왕. 셋이 만나 체커가 생겨났다고 여겨집니다.","s":["체커의 조상으로 여겨지는 것은 5×5개의 점을 선으로 이은 판에서 노는 '알케르케'입니다. 아랍어로는 '키르크'라 불렸고, 10세기의 《노래의 책》에 이름이 나옵니다. 무어인이 스페인에 전했고, 13세기 카스티야 왕 알폰소 10세가 만들게 한 《놀이의 책》에 놀이법이 적혀 있습니다.","12세기 무렵, 아마도 남프랑스에서 알케르케의 말을 체스판 위에서 움직이게 되었습니다. 이것이 '피에르주'입니다. 말은 당시 체스의 여왕 '페르즈'와 같은 이름으로 불렸습니다.","적진 끝까지 간 말이 강해지는 '승급'은 13세기 중엽의 연대기에 벌써 적혀 있습니다. 체스의 졸이 여왕이 되는 규칙을 받아들인 것인지도 모릅니다.","큰 변화는 1535년 무렵 프랑스에서 일어났습니다. 잡을 수 있는 말이 있으면 반드시 잡아야 하는 '강제 잡기'가 더해져, 이 게임은 '강제 게임'이라 불렸습니다. 오늘날 영국과 미국의 체커는 이 갈래를 잇고 있습니다.","한편 강제 잡기가 없는 옛 방식은 '여성을 위한 순한 게임'이라 불리며 남았고, 뒤에 10×10 판의 국제 규칙으로 이어졌습니다. 같은 조상에서 여러 '여왕의 게임'이 갈라져 나온 것입니다."],"quiz":[["체커의 조상으로 여겨지는 게임은?","알케르케","세네트","육박","만칼라"],["'강제 잡기'가 더해진 것은 언제 어디서?","1535년 무렵의 프랑스","10세기의 바그다드","1900년의 미국","8세기의 일본"],["피에르주의 말은 무엇과 같은 이름으로 불렸을까요?","체스의 여왕(페르즈)","체스의 왕","주사위","기사"]],"kf":["아랍의 알케르케 말을 체스판 위에서 움직이게 되면서 생겨난 게임","대각선으로 나아가고 상대 말을 뛰어넘어 잡는다. 끝까지 가면 ‘승격’해 강해진다","1535년 무렵 ‘강제 잡기’가 더해졌고, 2007년에는 완전히 풀렸다"],"more":[{"h":"점과 선의 판에서 체스판으로","p":["알케르케 판은 5×5, 25개의 점을 선으로 이은 것입니다. 양쪽이 12개씩 말을 놓고, 비어 있는 가운데 점부터 움직이기 시작합니다. 말은 선을 따라 나아가며 옆의 상대 말을 뛰어넘어 잡습니다.","이 말을 체스판 위로 옮기면서 한쪽 색의 칸만 쓰게 되었습니다. 8×8 판의 검은 칸은 32개. 저마다 자기 앞의 3줄에 채우면 12개씩이 되어, 알케르케와 같은 수가 됩니다."],"cap":["알케르케 판과 처음 배치. 5×5 점을 가로·세로·대각선으로 잇고, 12개씩 말을 놓아 가운데만 비운다"]},{"h":"뛰어넘어 잡고, 승격해 강해진다","p":["말은 대각선 앞으로 한 칸씩 나아가고, 옆의 상대 말 너머가 비어 있으면 뛰어넘어 잡습니다. 잡은 뒤에도 잡을 말이 있으면 계속 뜁니다. 잡을 수 있으면 반드시 잡아야 하는 것이 지금 체커의 규칙입니다.","상대 진영 맨 끝까지 가면 말을 두 개 겹쳐 ‘킹’이 되고, 뒤로도 갈 수 있습니다. 10×10 판의 국제 규칙에서는 킹이 대각선으로 몇 칸이든 달릴 수 있어 종반 싸움이 확 달라집니다."],"cap":["체커의 잡기와 승격. 빨간 말이 흰 말 두 개를 잇달아 뛰어넘어 잡고(×), 나중에 맨 끝 줄에 닿아 말을 두 개 겹친 ‘킹’이 된다"]},{"h":"풀린 게임, 퍼져 가는 가족","p":["캐나다의 조너선 섀퍼 등은 체커 프로그램 ‘치누크’를 만들었습니다. 1992년에는 40년 넘게 거의 지지 않은 명인 매리언 틴슬리와 대결했고, 틴슬리가 이겼습니다. 섀퍼 등은 계산을 이어가, 2007년 양쪽이 최선을 다하면 체커는 무승부가 된다는 것을 증명했습니다.","한편 같은 조상에서 나온 가족은 세계 곳곳에 남아 있습니다. 10×10 국제 규칙, 러시아의 샤시키, 가로세로로 움직이는 튀르키예의 다마, 12×12로 하는 캐나다 체커 등이 지금도 나라마다 대회를 엽니다."],"cap":[]}],"tl":[["10세기","《노래의 책》에 키르크(알케르케)의 이름이 나옴"],["12세기 무렵","남프랑스에서 피에르주가 생겨남"],["1283년","알폰소 10세의 『놀이의 책』에 알케르케 놀이법"],["1535년 무렵","프랑스에서 ‘강제 잡기’가 더해짐"],["1547년","스페인의 토르케마다가 다마에 관한 첫 책을 냄"],["18세기","프랑스와 네덜란드에서 10×10 판이 퍼짐"],["1992년","틴슬리가 프로그램 ‘치누크’와의 대결에서 승리"],["2007년","최선을 다하면 체커는 무승부임이 증명됨"]]},"reversi":{"title":"리버시와 오델로, 누가 만들었을까","lead":"흑백의 돌을 끼워 뒤집는 게임. 그 발명을 두고 19세기 영국에서 두 남자가 다퉜습니다.","s":["1880년대 런던에서 루이스 워터먼과 존 W. 몰릿이라는 두 영국인이 저마다 자기가 이 게임의 발명자라고 주장하며 상대를 사기꾼이라 불렀습니다.","몰릿의 게임은 '어넥세이션(합병)'이라는 이름으로 십자 모양 판을 썼습니다. 워터먼의 '리버시'는 보통의 8×8 판을 씁니다. 오늘날 전해지는 것은 워터먼의 형태입니다. 이름을 둘러싼 다툼은 재판까지 갔습니다.","리버시는 유럽에 퍼져, 1893년에는 독일의 라벤스부르거사가 초기 상품 중 하나로 내놓았습니다. 일본에서도 메이지 시대 책에 소개되어 '겐페이고'라고도 불렸습니다.","하지만 인기는 오래가지 않았습니다. 1971년 하세가와 고로가 처음 네 돌을 가운데에 엇갈려 놓는 방식으로 정한 게임을 '오델로'로 내놓아 일본에서 크게 유행했습니다.","이름은 셰익스피어의 희곡 《오셀로》에서 왔다고 합니다. 검은 피부의 장군 오셀로와 흰 피부의 아내 데스데모나를 흑백의 돌에 겹친 것입니다. 오늘날 대회 규칙은 이 오델로의 형태입니다."],"quiz":[["리버시 발명을 두고 다툰 두 사람은 언제, 어디 사람?","19세기 영국","18세기 프랑스","20세기 일본","16세기 이탈리아"],["몰릿의 '어넥세이션' 판은 어떤 모양?","십자 모양","원 모양","삼각형","8×8 사각형"],["1971년에 '오델로'를 내놓은 사람은?","하세가와 고로","혼인보 슈사쿠","루이스 워터먼","라벤스부르거"]],"kf":["상대 돌을 자기 돌로 끼워 뒤집고, 마지막에 돌이 많은 쪽이 이기는 게임","1880년대 런던에서 두 영국인이 발명자 자리를 다퉜다","1970년대 일본에서 ‘오델로’로 크게 유행했고, 2023년에는 최선이면 무승부임이 밝혀졌다"],"more":[{"h":"끼워서 뒤집는다","p":["돌은 상대 돌을 자기 돌로 끼울 수 있는 칸에만 놓을 수 있습니다. 끼우는 방향은 가로·세로·대각선의 8방향이고, 한 번에 여러 방향을 끼울 수 있습니다. 끼인 돌은 모두 뒤집혀 자기 색이 됩니다.","놓을 칸이 없으면 패스하고, 둘 다 놓을 수 없게 되면 끝납니다. 네 귀퉁이의 돌은 다시는 끼이지 않으므로, 귀를 차지하면 크게 유리합니다. 당장의 돌 수보다 상대가 둘 수 있는 곳을 줄이는 것이 중요하다고 합니다."],"cap":["돌을 놓아 뒤집는 원리. 빨간 고리 칸에 흑을 놓으면 가로·세로·대각선 세 방향에서 백을 끼우고, 금색 테의 백 7개가 모두 흑으로 바뀐다"]},{"h":"처음 네 개의 돌","p":["초기 리버시에서는 처음 네 돌을 두 사람이 가운데 네 칸에 차례로 놓았습니다. 그래서 같은 색이 나란한 모양도, 엇갈린 모양도 될 수 있었습니다.","오델로는 처음 네 돌을 엇갈리게 놓도록 정했습니다. 처음부터 흑백 어느 돌이든 끼우기 쉬워, 초반부터 치열한 공방이 벌어집니다. 지금의 세계 대회도 이 모양에서 시작합니다."],"cap":["처음 네 돌. 왼쪽: 초기 리버시의 놓는 법의 한 예(같은 색이 가로로 나란히). 오른쪽: 오델로에서 정한 엇갈리게 놓는 법"]},{"h":"사람과 컴퓨터","p":["오델로는 일본에서 세계로 퍼졌고, 1977년에는 도쿄에서 제1회 세계 선수권이 열렸습니다. 규칙이 간단한 만큼 수읽기의 깊이로 승부가 갈리며, 강한 선수는 수십 수 앞을 내다봅니다.","1997년 프로그램 ‘로지스텔로’는 세계 챔피언 무라카미 다케시와 6판을 두어 모두 이겼습니다. 2023년에는 8×8 오델로가 양쪽이 최선을 다하면 무승부가 된다는 것이 계산으로 밝혀졌습니다."],"cap":[]}],"tl":[["1880년대","런던에서 워터먼과 몰릿이 발명을 다툼"],["1893년","독일 라벤스부르거 사가 리버시를 내놓음"],["메이지 시대","일본 책에 ‘겐페이고’로 소개됨"],["1973년","일본에서 ‘오델로’ 세트 발매"],["1977년","도쿄에서 제1회 세계 오델로 선수권"],["1997년","로지스텔로가 세계 챔피언 무라카미 다케시에게 6전 전승"],["2023년","8×8 오델로는 최선이면 무승부임이 밝혀짐"]]},"mancala":{"title":"만칼라는 어디서 생겨났을까","lead":"구멍에서 구멍으로 씨를 뿌리듯 돌을 나누는 게임. 아프리카와 아시아 곳곳에서 수백 가지 이름으로 즐겨 왔습니다.","s":["만칼라는 판에 늘어선 구멍에서 돌이나 씨앗을 집어 앞의 구멍에 하나씩 뿌려 나가는 게임들을 통틀어 부르는 이름입니다. 아랍어 '나칼라(옮기다)'에서 온 말이라고 합니다.","이름도 놀이법도 지역마다 제각각이어서, 서아프리카의 오와레, 동아프리카의 바오, 튀르키예의 만갈라, 동남아시아의 총칵 등 수백 가지가 있습니다. 두 줄도 네 줄도 있고 구멍 수도 다양합니다.","아주 오래된 게임이라고들 하지만, 확실한 증거는 뜻밖에 새롭습니다. 지금까지 연대가 분명한 가장 오래된 판은 고대 악숨 왕국 유적(에리트레아의 마타라, 에티오피아의 예하)에서 나온 6~7세기 무렵의 토기와 돌 판으로 여겨집니다.","그보다 오래되었다는 예도 있지만, 그 구멍 줄이 정말 만칼라를 위한 것이었는지는 알 수 없어 연구자들 의견이 갈립니다. 악숨에서 아라비아와 아프리카 내륙으로 퍼졌다는 설이 유력합니다.","정리된 놀이법 기록은 17세기 무렵에야 나타납니다. 대백과의 만칼라에서는 오와레, 만갈라 등 8가지 규칙으로 즐길 수 있습니다."],"quiz":[["'만칼라'의 바탕이 된 아랍어의 뜻은?","옮기다","씨앗","구멍","왕"],["연대가 분명한 가장 오래된 만칼라 판이 나온 곳은?","고대 악숨 왕국 유적(에티오피아·에리트레아)","로마의 콜로세움","중국의 만리장성","영국의 스톤헨지"],["서아프리카에서 즐기는 만칼라는?","오와레","육박","타플","파치시"]],"kf":["구멍의 돌을 모두 꺼내 다음 구멍부터 하나씩 나눠 넣으며 나아가는 ‘씨뿌리기’ 게임의 무리","연대가 확실한 가장 오래된 판은 6~7세기 무렵 고대 악숨 왕국의 것","두 줄, 네 줄, 창고가 있는 것 등 지역마다 판도 규칙도 다양하다"],"more":[{"h":"씨뿌리기","p":["만칼라에서는 자기 쪽 구멍 하나를 골라 돌을 모두 꺼내고, 다음 구멍부터 하나씩 넣어 갑니다. 밭에 씨를 뿌리는 듯한 이 동작을 ‘씨뿌리기’라고 부릅니다.","서아프리카의 오와레는 48개의 돌을 12개 구멍에 4개씩 넣고 시작합니다. 마지막 돌이 들어간 상대 구멍이 2개나 3개가 되면 그 돌을 가져옵니다. 몇 개를 넣으면 어디서 멈추는지 미리 세어 읽는 힘이 중요한 게임입니다. 오와레는 대서양을 건너 카리브해 섬들에도 전해졌습니다."],"cap":["오와레의 씨뿌리기. 금색 고리 구멍의 돌 3개를 시계 반대 방향으로 하나씩 넣고, 마지막 하나로 상대 구멍이 딱 3개가 되어 그 3개를 가져간다(빨간 고리)"]},{"h":"두 줄과 네 줄","p":["만칼라 판은 크게 두 줄짜리와 네 줄짜리로 나뉩니다. 서아프리카와 아시아에는 두 줄 판이 많고, 네 줄 판은 동아프리카에서 남부 아프리카까지 퍼져 있습니다. 탄자니아의 바오는 4줄×8구멍이며, 이름은 스와힐리어로 ‘판’이라는 뜻입니다.","동남아시아의 총칵이나 숭카처럼 판 양 끝에 잡은 돌을 모으는 큰 구멍 ‘창고’가 있는 것도 있습니다. 20세기 미국에서 태어난 ‘칼라’도 창고가 있는 두 줄 형태로, 2000년에는 6구멍에 4개씩으로 시작하는 칼라는 선수가 반드시 이긴다는 것이 계산으로 밝혀졌습니다."],"cap":["만칼라 판 모양의 예. 2줄×6구멍(오와레 등), 2줄×7구멍에 양 끝의 창고(동남아시아의 총칵 등), 4줄×8구멍(동아프리카의 바오 등)"]},{"h":"기록한 사람들","p":["만칼라를 자세히 쓴 첫 유럽 학자는 영국의 토머스 하이드로 알려져 있습니다. 1694년의 『동양의 놀이에 대하여』에서 아랍어 이름과 함께 놀이법을 소개했습니다.","1836년에는 에드워드 W. 레인이 카이로 사람들의 생활을 그린 책에서 카페에서 즐기는 ‘만칼라’를 기록했습니다. 지금은 연구자들이 곳곳의 놀이법을 모아, 기록된 규칙이 수백 가지에 이릅니다."],"cap":[]}],"tl":[["6~7세기","고대 악숨 왕국 유적에서 연대가 확실한 가장 오래된 판"],["1694년","토머스 하이드가 『동양의 놀이에 대하여』에서 만칼라 소개"],["18~19세기","오와레 등이 대서양을 건너 카리브해 섬들로"],["1836년","E. W. 레인이 카이로의 만칼라를 기록"],["20세기 중반","미국에서 창고가 있는 두 줄 만칼라 ‘칼라’ 발매"],["2000년","6구멍 4개의 칼라는 선수 필승으로 계산됨"]]},"morris":{"title":"나인 멘스 모리스는 어디에나 있다","lead":"신전 지붕, 바이킹의 배, 대성당의 돌 벤치. 이 판의 선은 사람이 모이는 곳마다 새겨져 왔습니다.","s":["나인 멘스 모리스는 세 겹 사각형의 24개 점에 9개씩 말을 놓고, 셋을 나란히 세운 ‘밀’로 상대 말을 잡는 게임입니다. ‘모리스’는 춤과는 관계없고, ‘말·산가지’를 뜻하는 라틴어 메렐루스에서 왔다고 합니다.","이집트 쿠르나 신전의 지붕돌에 새겨진 판이 기원전 1400년경의 가장 오래된 예로 자주 소개됩니다. 하지만 연구자 베르거는 같은 곳의 선화에 콥트 십자가가 섞여 있다고 지적하며 ‘연대를 정할 수 없다’고 했습니다. 확실한 예는 로마 시대부터입니다.","900년경 노르웨이의 고크스타 배에서는 갑판 널빤지에 이 판이 새겨져 있었습니다. 영국에서는 캔터베리, 솔즈베리 같은 대성당 회랑의 돌 벤치에도 판이 남아 있습니다.","1283년에 만들어진 알폰소 10세의 『놀이의 책』에는 주사위로 하는 그림까지 있습니다. 셰익스피어는 『한여름 밤의 꿈』에서 장마로 ‘나인 멘스 모리스가 진흙에 묻혔다’고 썼습니다. 마을 풀밭에 파 놓은 판 이야기입니다.","1996년 독일의 랄프 가서는 컴퓨터로 모든 국면을 조사해, 양쪽이 최선을 다하면 무승부가 된다는 것을 증명했습니다. 그래도 사람끼리 두면 지금도 충분히 재미있는 게임입니다."],"quiz":[["‘모리스’라는 이름의 유래로 알려진 것은?","라틴어의 ‘말(산가지)’","영국의 춤","사람 이름","배 이름"],["쿠르나 신전의 판에 대해 연구자가 지적한 것은?","연대를 정할 수 없다","금으로 만들었다","중국에서 왔다","로마 황제의 것이었다"],["1996년 컴퓨터로 증명된 것은?","최선을 다하면 무승부","선수가 반드시 이긴다","후수가 반드시 이긴다","말 8개면 충분하다"]],"kf":["세 겹 사각형의 24개 점에 9개씩 말을 놓고, 셋을 나란히 세워 상대 말을 잡는 게임","로마 시대부터 배의 갑판, 대성당의 돌 벤치 등 사람이 모이는 곳마다 판이 새겨졌다","1996년 컴퓨터로 모든 국면을 조사해, 최선이면 무승부임이 증명되었다"],"more":[{"h":"놓고, 움직이고, 뛴다","p":["게임은 세 단계로 진행됩니다. 먼저 두 사람이 번갈아 9개의 말을 빈 점에 놓습니다. 모두 놓으면, 선을 따라 옆의 빈 점으로 말을 하나씩 움직입니다.","선 위에 말 셋을 한 줄로 세우면 ‘밀’이 되어 상대 말 하나를 판에서 들어냅니다. 말이 셋으로 줄면 어느 빈 점으로든 ‘뛸’ 수 있다는 규칙도 흔히 씁니다. 말이 둘이 되거나 움직일 수 없게 된 쪽이 집니다."],"cap":["나인 멘스 모리스 판. 백이 가장 바깥 변에 셋을 세워 ‘밀’을 만들었으므로(금색) 흑 말 하나를 잡을 수 있다(빨간 ×)"]},{"h":"셋에서 열둘까지","p":["모리스 가족은 말의 수로 불립니다. 셋씩 하는 스리 멘스 모리스는 틱택토에 가까운 작은 판입니다. 여섯씩 하는 식스 멘스 모리스는 사각형이 두 겹인 판을 씁니다.","열둘씩 하는 트웰브 멘스 모리스는 나인 멘스 판에 대각선을 더한 것입니다. 남아프리카에서는 ‘모라바라바’라 불리며, 소 치는 소년들이 땅에 그려 놀았다고 하고, 지금은 대회도 열립니다."],"cap":["판 크기 비교. 숫자는 한 사람의 말 수로, 스리·식스·나인·트웰브 멘스 모리스의 판"]},{"h":"체스 챔피언과 컴퓨터","p":["체스 세계 챔피언 에마누엘 라스커도 이 게임에 빠진 사람이었습니다. 1931년의 책 『여러 민족의 보드게임』에서 말을 열 개씩으로 하고, 놓는 도중에도 움직일 수 있는 방식을 제안했습니다.","1996년 스위스의 랄프 가서는 모든 종반 국면을 계산한 표와 초반부터의 탐색을 합쳐, 양쪽이 최선을 다하면 나인 멘스 모리스는 무승부임을 보였습니다. 판의 점은 24개뿐이지만 국면 수는 수십억에 이릅니다."],"cap":[]}],"tl":[["로마 시대","제국 곳곳의 돌에 판이 새겨짐(확실한 옛 예)"],["900년 무렵","노르웨이 고크스타 배의 갑판에 판이 새겨짐"],["1283년","알폰소 10세의 『놀이의 책』에 모리스가 그려짐"],["중세","영국 대성당 회랑의 벤치에 판이 새겨짐"],["1590년대","셰익스피어 『한여름 밤의 꿈』에 진흙으로 메워진 판이 나옴"],["1931년","라스커가 『여러 민족의 보드게임』에서 새 방식 제안"],["1996년","가서가 ‘최선이면 무승부’를 증명"]]},"patolli":{"title":"아즈텍의 콩 경주, 파톨리","lead":"십자 모양 판과 구멍 뚫린 콩 주사위. 내기가 너무 뜨거워 스페인 사람들이 금지한 게임입니다.","s":["파톨리는 멕시코 아즈텍 사람들이 즐긴 경주 게임입니다. 이름은 ‘콩’이라는 뜻으로, 한쪽 면에 구멍이나 표시를 한 붉은 콩 5개를 던져 표시가 나온 수만큼 말을 움직였습니다. 판은 돗자리나 땅에 그린 십자 모양 칸입니다.","16세기에 이 지역을 기록한 디에고 두란은, 던지기 전에 향을 피우고 콩에게 빌었으며 놀이의 신 마쿠일소치틀에게 승리를 빌었다고 썼습니다.","귀족들은 보석과 옷, 때로는 자기 몸까지 걸었고, 져서 노예가 된 사람도 있었다고 합니다. 황제 목테수마가 귀족들의 대국을 지켜보았다는 이야기도 전해집니다.","스페인 수도사들은 내기와 옛 신들에 대한 기도를 싫어해 파톨리를 금지하고, 판을 부수고 콩을 태웠습니다. 그래서 도구는 거의 남아 있지 않습니다. 그러나 돌바닥이나 바위에 새겨진 판은 테오티우아칸과 마야 유적, 1977년에는 할리스코주의 암각화 속에서도 발견되었습니다.","십자 모양 판에서 말을 돌리는 점은 인도의 파치시와 꼭 닮았습니다. 1878년 영국의 타일러는 ‘아시아에서 전해졌을 것’이라고 했지만, 지금은 따로 생겨났다는 생각이 일반적입니다."],"quiz":[["파톨리에서 주사위 대신 던진 것은?","표시한 콩","동물 뼈","조개","나무 막대"],["기록에 나온 파톨리 금지 이유는?","내기와 옛 신들에 대한 기도","판이 너무 컸다","콩이 비쌌다","왕이 졌다"],["파톨리 판과 꼭 닮은 게임은?","파치시","바둑","체커","만칼라"]],"kf":["아즈텍 사람들이 표시한 콩을 던져 십자 모양 판에서 말을 나아가게 한 경주 게임","내기와 신들에 대한 기도가 얽혀 있어 스페인 수도사들에게 금지되었다","인도의 파치시와 꼭 닮았지만, 따로따로 생겨난 것으로 여겨진다"],"more":[{"h":"십자 길과 52칸","p":["파톨리 판은 천이나 돗자리, 돌바닥 위에 그린 십자 모양의 길입니다. 복원에서는 네 팔마다 두 줄의 칸이 늘어서고, 가운데 4칸과 합쳐 52칸으로 보는 경우가 많습니다.","52라는 수는 아즈텍 달력이 한 바퀴 도는 52년과 같습니다. 그래서 판을 달력이나 시간의 흐름에 겹쳐 보는 연구자도 있습니다. 말을 길을 따라 한 바퀴 돌려 먼저 돌아온 사람이 이겼습니다."],"cap":["흔히 복원되는 파톨리 판. 네 팔에 2줄×6칸의 길이 있고 가운데 4칸과 합쳐 52칸. 팔 끝의 붉은 칸은 특별한 칸으로 여겨진다"]},{"h":"콩 다섯 알","p":["주사위 대신 던진 것은 한쪽 면에 구멍이나 표시를 한 콩 다섯 알입니다. 표시가 나온 수만큼 말을 나아가게 합니다. 다섯 알 모두 표시가 나오는 것은 32번에 1번뿐입니다.","던지기 전에 콩에게 말을 걸고, 놀이의 신 마쿠일소치틀의 이름을 부르며 빌었다고 합니다. 16세기의 『마글리아베키아노 코덱스』에는 이 신이 지켜보는 가운데 파톨리를 둘러싼 사람들이 그려져 있습니다."],"cap":["콩 다섯 알 중 표시한 면이 위로 나온 수(0~5)와 나오기 쉬움(32번당). 콩마다 앞뒤가 같은 확률로 나온다고 할 때"]},{"h":"파치시와 꼭 닮은 꼴","p":["십자 모양 판 둘레를 말이 돌고, 몇 개를 던져 위로 나온 수만큼 나아간다. 파톨리와 인도의 파치시·차우파르는 놀랄 만큼 닮았습니다. 1878년 영국의 인류학자 타일러는 이 닮음이 우연이 아니라 아시아에서 전해진 표시라고 주장했습니다.","하지만 바다를 건너 전해졌다는 증거는 발견되지 않았습니다. 지금은 서로 다른 곳에서 사람들이 ‘도는 길’과 ‘던지는 도구’라는 같은 생각에 각자 이르렀다고 보는 것이 일반적입니다."],"cap":["인도의 차우파르를 그린 그림(1694~95년). 십자 판 둘레를 말이 도는 방식이 파톨리와 많이 닮았다"]}],"tl":[["테오티우아칸 시대","돌바닥에 십자 모양 판이 새겨짐"],["1519~21년","스페인이 아즈텍을 정복"],["16세기","『마글리아베키아노 코덱스』에 파톨리와 마쿠일소치틀이 그려짐"],["1577년 무렵","사아군이 『피렌체 코덱스』에 파톨리를 기록"],["1581년 무렵","두란이 기도와 내기의 모습을 기록"],["1878년","타일러가 아시아 기원설 발표"],["1977년","할리스코주의 암각화 속에서 판이 발견됨"]]},"xiangqi":{"title":"샹치의 강과 포","lead":"판 한가운데의 ‘강’과, 말을 뛰어넘어 잡는 ‘포’. 중국 장기는 언제 지금의 모습이 되었을까요?","s":["샹치(象棋)는 9×10 선의 교차점에 말을 놓는 중국 장기입니다. 말은 글자를 쓴 둥근 원판이고, 체스처럼 칸 안이 아니라 선 위를 움직입니다.","오래된 단서는 당나라 재상 우승유(779~847)의 괴담집 『현괴록』입니다. 어떤 남자가 꿈에서 본 작은 군대 이야기에 천마·장·거·갑(보병)이 나오고, 포를 떠올리게 하는 대목도 있습니다. 다만 판이나 움직임은 지금과 같지 않습니다.","9×10 판과 강, 포가 갖춰진 지금의 형태는 송나라(960~1279) 기록에 나타납니다. 뤄양의 북송 무덤에서는 말 한 벌이 발견되었습니다.","강에는 흔히 ‘초하한계(楚河漢界)’라고 쓰는데, 기원전 3세기에 항우의 초와 유방의 한이 천하를 다툰 경계에서 왔다고 합니다. 장은 ‘궁’ 밖으로 나갈 수 없고, 두 장이 사이에 말 없이 마주 보아서도 안 됩니다.","포는 말 하나를 뛰어넘을 때만 상대를 잡을 수 있습니다. 샹치는 베트남에서도 ‘꺼뜨엉’으로 사랑받고, 한반도에서는 아주 비슷한 장기로 자랐습니다. 대백과에서는 샹치와 장기를 모두 즐길 수 있습니다."],"quiz":[["샹치의 말이 움직이는 곳은?","선의 교차점","칸 안","원 위","육각형 칸"],["지금 형태의 샹치가 기록에 나타나는 시대는?","송","한","명","청"],["포가 상대 말을 잡을 때의 규칙은?","말 하나를 뛰어넘는다","곧게 한 칸 간다","대각선으로 두 칸 간다","강을 건넌 뒤에만"]],"kf":["9×10 선의 교점에 글자를 쓴 둥근 말을 놓고 싸우는 중국의 장기","판 가운데에 ‘강’, 양쪽에 장수가 사는 ‘궁’이 있고, 말마다 움직일 수 있는 곳이 정해져 있다","송나라 때 지금의 모습이 되었고, 지금도 중국과 베트남에서 수천만 명이 즐긴다"],"more":[{"h":"강과 궁이 있는 판","p":["말은 한쪽에 16개로, 장(수) 1, 사 2, 상 2, 마 2, 차 2, 포 2, 졸(병) 5입니다. 같은 역할의 말이라도 홍과 흑의 글자가 조금 다른 것이 있습니다.","장과 사는 궁 밖으로 나갈 수 없고, 상은 강을 건널 수 없습니다. 졸은 강을 건너기 전에는 앞으로만 가지만, 건너면 옆으로도 움직일 수 있습니다. 마는 나아가려는 방향 바로 옆에 말이 있으면 뛸 수 없습니다. 판의 구조 자체가 말의 역할을 정하는 셈입니다."],"cap":["샹치의 처음 배치. 위가 흑, 아래가 홍. 가운데 ‘楚河 漢界’가 강, 위아래의 대각선이 그어진 3×3이 궁"]},{"h":"뛰어넘는 포","p":["포는 평소에는 차처럼 가로세로로 얼마든지 갑니다. 그러나 상대 말을 잡을 때만은 사이에 꼭 한 개의 말(어느 편이든)을 두고 그것을 뛰어넘어야 합니다.","이 ‘다리’가 되는 말을 쓰는 법이 샹치만의 수싸움을 낳습니다. 초반에 포를 가운데로 옮기는 ‘중포’는 지금도 가장 인기 있는 시작 중 하나입니다."],"cap":["포로 잡는 법. 홍의 포가 사이에 있는 흑 마를 딱 한 개 뛰어넘어 그 너머의 흑 차를 잡는다"]},{"h":"기보와 명인","p":["명나라 때는 명국과 박보를 모은 책이 많이 만들어졌습니다. 1570년의 『적정아취』와 1632년의 『귤중비』는 지금도 연구되는 고전입니다.","20세기에는 후룽화가 중국 전국 대회에서 10연패를 이루었고, 1993년에는 세계상기연합회가 생겨 국경을 넘는 대회가 열리게 되었습니다. 중국과 베트남의 공원에서는 오늘도 판을 둘러싼 사람들의 원이 생깁니다."],"cap":[]}],"tl":[["9세기","우승유의 『현괴록』에 장·차·마 등의 말이 나옴"],["송(960~1279년)","9×10 판, 강, 포가 갖춰진 지금의 모습이 기록에 나타남"],["북송","뤄양의 무덤에 말 한 벌이 묻힘"],["1570년","기보집 『적정아취』"],["1632년","기보집 『귤중비』"],["1960~70년대","후룽화가 전국 대회 10연패"],["1993년","세계상기연합회 설립"]]},"backgammon":{"title":"백개먼은 5000년 전부터 있었을까?","lead":"‘세계에서 가장 오래된 백개먼’이라 불리는 판과 진짜 조상들. 페르시아 왕궁에서 뉴욕의 클럽까지.","s":["이란의 ‘불탄 도시’ 샤흐레 소흐테에서는 약 5000년 전의 판과 말 60개, 주사위가 나와 ‘세계에서 가장 오래된 백개먼’으로 자주 소개됩니다. 하지만 이 판은 부조한 뱀의 똬리로 20개쯤의 칸을 만든 것으로, 지금의 백개먼과는 모양이 다릅니다.","백개먼의 직접적인 조상으로 여겨지는 것은 페르시아의 ‘나르드’로, 3~6세기쯤 나타났습니다. 7~9세기에 쓰인 중세 페르시아어 이야기에서는, 인도에서 보낸 체스의 수수께끼를 푼 재상 보조르그메르가 답례로 나르드를 만들었다고 합니다.","로마에도 주사위 3개로 하는 판 게임 ‘타불라’가 있었습니다(이야기 3의 황제 제논의 대국이 바로 그것). 이런 ‘테이블즈’ 무리가 유럽 전역에 퍼져 프랑스의 트릭트랙 같은 많은 친척이 생겨났습니다.","‘백개먼’이라는 이름은 17세기 영국에서 나타났고, 1743년에는 에드먼드 호일이 규칙과 전법을 책으로 정리했습니다.","마지막 큰 발명은 1920년대 뉴욕의 클럽에서 생겼다고 하는 더블링 큐브입니다. 도중에 판돈을 두 배로 올릴 수 있는 이 정육면체 덕분에, 백개먼은 ‘언제 승부를 걸지’를 읽는 깊은 게임이 되었습니다."],"quiz":[["샤흐레 소흐테의 판은 어떤 모양?","뱀의 똬리로 칸을 만든 판","지금의 백개먼과 같다","둥근 원판","십자 모양"],["이야기에서 나르드를 만든 사람은?","재상 보조르그메르","황제 제논","에드먼드 호일","알폰소 10세"],["1920년대 뉴욕에서 생겼다고 하는 것은?","더블링 큐브","주사위 2개","24개의 삼각형","말 15개"]],"kf":["24개의 삼각형 위에서 15개의 말을 주사위 두 개로 나아가게 하고, 먼저 모두 판 밖으로 내보내는 쪽이 이긴다","직접적인 조상은 페르시아의 나르드와 로마의 타불라 같은 ‘테이블즈’ 가족","더블링 큐브와 컴퓨터가 20세기에 새로운 깊이를 더했다"],"more":[{"h":"말 15개와 삼각형 24개","p":["판에는 24개의 길쭉한 삼각형(포인트)이 있고, 두 사람은 각자 15개의 말을 가집니다. 주사위 두 개를 굴려 나온 눈만큼 말을 하나씩, 또는 한 말을 이어서 움직입니다. 같은 눈(더블)이 나오면 그 눈을 네 번 씁니다.","혼자 있는 상대 말에 멈추면 그 말을 가운데 ‘바’로 보낼 수 있습니다. 보내진 말은 상대 진영으로 다시 들어와야 합니다. 15개의 말을 모두 자기 진영에 모으면 판 밖으로 내보내기 시작하고, 먼저 다 내보낸 쪽이 이깁니다."],"cap":["백개먼의 처음 배치. 백은 24에서 1로(시계 반대 방향으로) 나아가며, 오른쪽 아래 1~6이 자기 진영. 흑은 반대로 나아간다"]},{"h":"가까울수록 맞히기 쉽다","p":["상대의 혼자 있는 말을 맞힐 수 있는지는 거리에 따라 크게 달라집니다. 6칸 앞이면 36가지 중 17가지로 맞지만, 7칸 앞이면 6가지로 떨어집니다.","이런 수를 알아 두면 어디에 말을 두면 위험한지 알 수 있습니다. 처음 배치에서 모든 말을 끝까지 옮기는 데 필요한 눈의 합은 둘 다 167입니다. 강한 사람은 이 ‘핍 카운트’를 세어 유불리를 판단합니다."],"cap":["혼자 있는 말을 몇 칸 앞에서 맞힐 수 있는가. 주사위 두 개의 36가지 중 맞히는 경우의 수(가는 길이 막히지 않은 경우)"]},{"h":"클럽에서 세계 대회로","p":["1743년 영국의 에드먼드 호일이 규칙과 전략을 정리한 책을 냈습니다. 19세기 영국에서는 가구 문에 그려질 만큼 사랑받았고, 1920년대 뉴욕의 클럽에서는 더블링 큐브가 생겨났습니다.","1964년 바하마에서 세계 대회가 열렸고, 1970년대에는 크게 유행했습니다. 1979년 한스 베를리너의 프로그램이 세계 챔피언 루이지 빌라를 이겼고, 1992년 무렵에는 자기 자신과 두며 배우는 ‘TD-개먼’이 인간 최상급에 가까운 실력에 이르렀습니다."],"cap":["백개먼을 두는 두 사람을 그린 장식장(1861년, 런던). 모리스 상회의 초기 가구"]}],"tl":[["기원전 3000년 무렵","샤흐레 수흐테에 똬리 모양 판과 말·주사위가 묻힘"],["3~6세기 무렵","페르시아에 나르드가 나타남"],["1743년","호일이 백개먼 책을 냄"],["1920년대","뉴욕에서 더블링 큐브가 생겨남"],["1964년","바하마에서 세계 대회"],["1979년","베를리너의 프로그램이 세계 챔피언에게 승리"],["1992년 무렵","자기 대국으로 배우는 TD-개먼 등장"]]},"hex":{"title":"두 수학자가 따로 발명한 헥스","lead":"덴마크의 시인과 미국의 젊은 천재. 서로 모른 채 같은 게임을 떠올렸습니다.","s":["헥스는 마름모꼴로 늘어선 육각형 칸에 번갈아 돌을 놓아, 자기 색의 마주 보는 두 변을 먼저 이으면 이기는 아주 단순한 게임입니다.","처음 생각한 사람은 덴마크의 수학자이자 시인 피트 하인이었습니다. 1942년 코펜하겐의 닐스 보어 연구소에서 소개했고, 같은 해 12월 26일 신문 『폴리티켄』에 ‘폴리곤’이라는 이름으로 실렸으며, 50장짜리 용지 묶음으로 팔렸습니다.","그런데 1943년 하인이 덴마크를 떠나야 했고, 게임도 자취를 감췄습니다. 몇 년 뒤인 1948~49년, 미국 프린스턴 대학교 대학원생 존 내시가 전혀 따로 같은 게임을 생각해 냈습니다. 동료들은 이것을 ‘내시’라고 불렀다고 합니다.","1952년 파커 브러더스가 ‘헥스’라는 이름으로 발매했고, 1957년 마틴 가드너가 과학 잡지 연재에서 소개하면서 세계에 알려졌습니다.","헥스에는 무승부가 없습니다. 그리고 내시는 ‘선수에게는 반드시 이기는 방법이 있다’는 것을, 실제 수를 보이지 않고 증명했습니다. 하지만 큰 판에서는 그 이기는 법을 아직도 모릅니다."],"quiz":[["헥스에서 이기는 조건은?","자기 색의 두 변을 잇는다","상대 돌을 모두 잡는다","왕을 둘러싼다","다섯 개를 잇는다"],["하인의 게임이 덴마크 신문에 실렸을 때의 이름은?","폴리곤","내시","콘택틱스","오델로"],["내시가 증명한 것은?","선수에게 필승법이 있다","후수가 반드시 이긴다","반드시 비긴다","이기는 구체적인 수"]],"kf":["육각형 칸에 번갈아 돌을 놓아, 자기 색의 마주 보는 두 변을 이으면 이긴다","1942년 덴마크의 하인, 1948~49년 미국의 내시가 따로 발명했다","무승부가 없고 선수 필승이 증명되었지만, 큰 판의 이기는 법은 아직 모른다"],"more":[{"h":"잇기만 하는 게임","p":["판은 마름모꼴로 늘어선 육각형 칸이며, 정식 크기는 11×11입니다. 빨강은 위와 아래 변, 파랑은 왼쪽과 오른쪽 변을 맡아 번갈아 하나씩 돌을 놓습니다. 놓은 돌은 움직이지 않고, 잡히지도 않습니다.","판이 다 차면 반드시 어느 한쪽이 이어져 있습니다. 육각형 칸은 꼭짓점으로만 맞닿는 일이 없어서, 상대의 길을 비집고 빠져나갈 수 없기 때문입니다. 1979년 수학자 데이비드 게일은 이 ‘무승부가 없다’는 성질이 수학의 유명한 정리인 브라우어르 고정점 정리와 같은 내용이라는 것을 보였습니다."],"cap":["7×7 헥스 판. 빨강은 위아래 변, 파랑은 좌우 변을 이으면 이긴다. 금색 테의 빨간 돌 줄이 위아래를 이었다"]},{"h":"다리와 사다리","p":["강한 사람이 즐겨 쓰는 것이 ‘다리’입니다. 바로 옆이 아니라 한 칸 띄워 돌을 놓으면, 두 돌 사이에 공통된 빈칸이 두 개 생깁니다. 상대가 한쪽을 막아도 다른 쪽에 두면 이어지므로, 사실상 이미 이어진 것과 같습니다.","판 가장자리에는 사다리처럼 돌을 늘어놓아 변에 닿는 모양 등 정해진 형태가 여럿 알려져 있습니다. 또 선수가 너무 유리하기 때문에, 두 번째 수에서 ‘선수의 돌을 자기 것으로 해도 된다’는 규칙(스왑)을 쓰는 것이 보통입니다."],"cap":["‘다리’ 모양. 두 빨간 돌은 사이의 빈칸 두 개(점선 원) 중 어느 쪽으로든 이어질 수 있다. 파랑이 한쪽에 두면 빨강은 다른 쪽에 두면 된다"]},{"h":"수학자의 게임","p":["내시는 만약 후수에게 필승법이 있다면 선수가 그것을 가로챌 수 있으니 모순이라는 ‘전략 훔치기’의 생각으로 선수 필승을 증명했습니다. 실제로 이기는 수를 보여 주지 않는 신기한 증명입니다.","1950년대에는 정보 이론의 아버지 클로드 섀넌이 전기 회로로 헥스를 두는 기계를 만들었습니다. 2010년대에는 9×9까지의 판이 컴퓨터로 모두 풀렸지만, 11×11 정식 판은 아직 풀리지 않았습니다."],"cap":[]}],"tl":[["1942년","하인이 덴마크 신문에 ‘폴리곤’ 발표"],["1948~49년","프린스턴의 내시가 같은 게임을 떠올림"],["1952년","파커 브라더스가 ‘헥스’로 발매"],["1950년대","섀넌이 전기 회로로 헥스를 두는 기계를 만듦"],["1957년","가드너가 과학 잡지 연재에서 소개"],["1979년","게일이 고정점 정리와의 연결을 보임"],["2010년대","9×9까지의 판이 컴퓨터로 풀림"]]},"foxgeese":{"title":"여우와 거위와 왕의 은 말","lead":"여우 한 마리와 많은 거위. 힘이 다른 두 진영이 싸우는 ‘사냥 게임’의 긴 역사입니다.","s":["여우와 거위는 여우 하나가 거위를 뛰어넘어 잡아먹고, 거위들은 여우를 움직이지 못하게 가두려는, 양쪽의 역할이 전혀 다른 게임입니다. 판은 33개의 점을 선으로 이은 십자 모양입니다.","오래된 단서는 14세기쯤 쓰인 아이슬란드의 『그레티르 사가』에 나오는 ‘할라타플’입니다. ‘꼬리 판’이라는 뜻으로, 꼬리는 여우 꼬리를 가리킨다고 봅니다. 북유럽의 타플에서 갈라져 나온 게임이었을 것입니다.","잉글랜드에서는 15세기 국왕 에드워드 4세의 회계 장부에 ‘금도금한 은 여우 2개와 사냥개 26개’를 샀다는 기록이 남아 있습니다. 두 벌의 말로, 당시에는 ‘여우와 사냥개’라고 불렸던 듯합니다.","원래의 거위 13마리로는 여우가 너무 유리해서, 뒤에 거위를 늘리는 방식이 퍼졌습니다. 19세기에는 빅토리아 여왕도 이 게임을 좋아했다고 전해집니다.","같은 십자 모양 판은 혼자 하는 페그 솔리테어에도 쓰입니다. 네팔의 바그찰처럼 호랑이나 늑대가 사냥감을 쫓는 사냥 게임은 세계 곳곳에 있습니다. 대백과에서는 여우와 거위도, 페그 솔리테어도 즐길 수 있습니다."],"quiz":[["할라타플의 ‘할라’는 무슨 뜻?","꼬리","여우","왕","눈"],["에드워드 4세의 장부에 있던 말은?","은 여우와 사냥개","금 거위","상아 왕","나무 주사위"],["같은 십자 모양 판을 쓰는 혼자 놀이는?","페그 솔리테어","스도쿠","솔리테어(카드)","칠교놀이"]],"kf":["여우 한 마리와 거위 13마리(뒤에는 17마리)가 33개 점의 십자 모양 판에서 싸운다","여우는 거위를 뛰어넘어 잡고, 거위는 여우를 에워싸 움직이지 못하게 하면 이긴다","같은 판은 페그 솔리테어에도 쓰이며, 이런 사냥 게임은 세계 곳곳에 있다"],"more":[{"h":"1 대 13","p":["여우는 선을 따라 한 칸씩 움직이고, 옆 거위 너머가 비어 있으면 뛰어넘어 잡습니다. 체커처럼 여러 마리를 이어서 뛰기도 합니다. 거위는 잡을 수 없고, 많은 놀이법에서 뒤로 물러날 수도 없습니다.","거위의 목표는 빈틈없이 늘어서 여우를 몰아붙여 움직이지 못하게 하는 것입니다. 13마리로는 여우가 너무 유리하다고 하며, 17마리로 늘리고 뒤로 물러날 수 없게 하면 잘 두었을 때 거위가 이길 수 있다고 합니다."],"cap":["여우와 거위 판. 33개 점을 선으로 이은 십자 모양. 거위 13마리가 위쪽에 서고, 여우(주황)는 바로 앞의 거위(×)를 뛰어넘어 그 너머 빈 점으로 가면 잡을 수 있다"]},{"h":"사냥 게임 가족","p":["수가 적은 강한 말이 수가 많은 약한 말을 쫓는 ‘사냥 게임’은 세계 곳곳에 있습니다. 네팔의 바그찰은 5×5 판에서 호랑이 4마리가 염소 20마리를 쫓습니다. 2004년에는 계산으로, 양쪽이 최선을 다하면 무승부가 된다는 것이 밝혀졌습니다.","19세기 독일에서 인기였던 ‘아살토’는 같은 십자 판에서 장교 2명이 병사 24명과 싸웁니다. 이쪽은 장교가 성을 지키고, 병사들이 성으로 쳐들어갑니다."],"cap":["사냥 게임의 수 비교. 왼쪽 주황이 사냥하는 쪽, 오른쪽 흰색이 쫓기는 쪽. 위부터 여우와 거위(1:13), 거위를 늘린 판(1:17), 네팔의 바그찰(4:20), 아살토(2:24)"]},{"h":"왕의 말에서 페그 솔리테어로","p":["잉글랜드 에드워드 4세(재위 1461~83년)의 회계 장부에는 금도금한 은 여우와 사냥개 말을 샀다는 기록이 있습니다. 왕족과 귀족의 즐거움이기도 했던 것입니다.","같은 33개 구멍의 십자 판은 혼자 하는 페그 솔리테어에도 쓰입니다. 1697년 프랑스 판화에는 이 혼자 놀이를 하는 귀부인이 그려져 있어, 페그 솔리테어의 가장 오래된 기록 중 하나로 꼽힙니다."],"cap":[]}],"tl":[["14세기 무렵","아이슬란드 『그레티르 사가』에 ‘할라타플’이 나옴"],["15세기 후반","에드워드 4세가 은 여우와 사냥개 말을 삼"],["1697년","프랑스 판화에 페그 솔리테어를 하는 귀부인"],["19세기","빅토리아 여왕이 좋아했다고 전해짐"],["19세기","같은 판의 ‘아살토’가 독일에서 인기"],["2004년","네팔의 바그찰은 최선이면 무승부로 밝혀짐"]]},"latrunculi":{"title":"로마 병사들의 판","lead":"로마 사람들이 빠져든 ‘용병 게임’. 규칙책은 남아 있지 않지만, 시와 일화, 땅속에서 나온 판이 실마리입니다.","s":["루두스 라트룬쿨로룸은 고대 로마에서 즐긴 2인용 전투 게임입니다. ‘라트룬쿨리’는 원래 용병이나 도적을 뜻했고, 말은 병사에 빗대어졌습니다.","말은 격자판 위를 움직이며, 상대 말을 자기 말 두 개로 끼우면 잡을 수 있었습니다. 1세기의 시 『피소 찬가』에는 말들이 나아가고 물러나며, 둘러싸인 말이 꼼짝 못 하게 되는 모습이 그려져 있습니다.","철학자 세네카는 황제 칼리굴라에게 사형을 선고받은 율리우스 카누스의 이야기를 전합니다. 데리러 온 백인대장이 왔을 때 카누스는 라트룬쿨리를 두고 있었고, 말을 세어 보고는 상대에게 “내가 죽은 뒤에 이겼다고 거짓말하지 말게”라고 했다고 합니다.","판은 로마 제국 곳곳에서 발견됩니다. 군 요새와 도시의 돌에 새긴 격자는 8×8에서 12×12 정도까지 다양합니다. 잉글랜드 스탠웨이의 무덤(1세기)에서는 판 위에 놓인 그대로의 유리 말이 나왔습니다.","자세한 규칙책은 남아 있지 않아, 지금의 놀이법은 연구자의 복원입니다. 대백과의 라트룬쿨로룸도 그런 복원 가운데 하나에 바탕을 둡니다."],"quiz":[["라트룬쿨로룸에서 상대 말을 잡는 방법은?","말 두 개로 끼운다","뛰어넘는다","주사위로 정한다","왕을 에워싼다"],["처형하러 데리러 왔을 때도 라트룬쿨리를 두고 있던 사람은?","율리우스 카누스","카이사르","네로","키케로"],["스탠웨이 무덤에서 판 위에 남아 있던 것은?","유리 말","금화","체스 말","트럼프"]],"kf":["고대 로마에서 즐긴, 병사에 빗댄 말로 싸우는 2인용 게임","상대 말을 두 말로 끼우면 잡는다. 움직일 수 없게 된 말에 관한 기록도 있다","규칙책 없이 시·일화·출토된 판으로 복원된다"],"more":[{"h":"끼우고, 에워싼다","p":["복원의 가장 자세한 근거는 1세기의 시 『피소 찬가』입니다. 한 말이 나아가 적을 꾀고, 다른 말이 그 뒤를 지키며, 적의 두 말에 끼인 말은 잃는다는 식으로 전장처럼 그려져 있습니다.","시에는 둘러싸여 움직이지 못하게 된 말도 나옵니다. 그래서 많은 복원은 끼워 잡기 외에 움직일 수 없게 된 말에 대한 규칙도 둡니다. 북유럽의 타플에도 끼워 잡는 비슷한 방식이 있습니다."],"cap":["라트룬쿨로룸의 잡는 법(복원). 왼쪽: 파란 화살표처럼 나아가 흰 말을 두 흑으로 끼우면 잡는다(×). 오른쪽: 사방이 막힌 흰 말은 움직일 수 없다"]},{"h":"양면 판","p":["시인 마르티알리스(1세기)는 선물에 붙인 시에서, 한쪽 면에서는 주사위 눈으로 말을 나아가게 하고 다른 면에서는 두 색의 병사가 싸우는 판을 노래했습니다. 운의 게임과 머리의 게임을 한 장의 판으로 즐긴 것입니다.","주사위를 쓰는 쪽은 ‘열두 줄’이라 불린 경주 게임으로 여겨지며, 뒷날의 타불라와 백개먼으로 이어집니다. 박물관 소장품의 주사위 탑(피르구스)도 로마 사람들이 쓴 도구입니다."],"cap":["마르티알리스가 노래한 양면 판의 이미지. 한쪽은 주사위로 열두 줄을 달리는 게임, 다른 쪽은 병사 게임의 격자"]},{"h":"땅속에서 나온 판","p":["로마 병사들은 요새의 돌이나 바닥에 격자를 새겨 놀았습니다. 브리튼섬의 하드리아누스 방벽 근처에서도, 독일·스페인·북아프리카에서도 새겨진 판이 발견되었습니다.","스탠웨이 무덤(1세기 중엽)에서는 나무 판은 썩었지만, 그 위의 흰색과 파란색 유리 말이 두다 만 것 같은 자리에 그대로 남아 있었습니다. 주인은 의사였을 것으로 보이며, 의료 도구도 함께 나왔습니다."],"cap":["주사위 탑(피르구스). 로마 사람들은 속임수를 막으려고 이런 탑에 주사위를 굴렸다"]}],"tl":[["기원전 1세기","바로가 라트룬쿨리의 이름을 적음"],["기원전 1세기 말","오비디우스가 사랑의 시에서 이 게임을 언급"],["1세기","『피소 찬가』가 게임의 모습을 시로 그림"],["1세기 중엽","스탠웨이 무덤에 말을 늘어놓은 판이 묻힘"],["1세기","세네카가 율리우스 카누스의 일화를 전함"],["1세기 말","마르티알리스가 양면 판을 노래함"],["1994년","셰들러가 놀이법 복원을 발표"]]},"amazons":{"title":"둘 때마다 판이 타 들어가는 게임","lead":"1988년 아르헨티나에서 태어난 ‘아마존스’. 체스 여왕의 움직임과 바둑의 집짓기가 하나가 되었습니다.","s":["아마존스는 10×10 판에서 저마다 4명의 ‘아마존’을 움직이는 2인용 게임입니다. 1988년 아르헨티나의 왈테르 삼카우스카스가 고안했습니다.","한 수는 두 동작으로 이루어집니다. 먼저 아마존을 체스의 여왕처럼 가로·세로·대각선으로 곧게 움직이고, 도착한 곳에서 같은 방식으로 화살을 쏩니다. 화살이 꽂힌 칸은 이제 아무도 지나갈 수 없습니다.","판은 한 수마다 한 칸씩 메워지고, 마지막에 움직일 수 없게 된 쪽이 집니다. 무승부는 없습니다.","종반이 되면 판은 화살 벽으로 여러 방으로 나뉩니다. 그러면 자기만 쓸 수 있는 빈칸이 많은 쪽이 이기므로, 바둑의 집처럼 세어 형세를 판단합니다.","첫 수만 해도 2000가지가 넘는 수가 있어 컴퓨터에게도 까다로운 게임입니다. 수학자들이 연구하고, 컴퓨터 대회에서도 종목이 되어 있습니다."],"quiz":[["아마존스가 태어난 나라는?","아르헨티나","브라질","스페인","멕시코"],["화살을 쏜 칸은 어떻게 될까?","아무도 지나갈 수 없게 된다","다음 차례에 사라진다","상대의 말이 된다","점수가 된다"],["아마존스에서 지는 쪽은?","먼저 움직일 수 없게 된 쪽","먼저 말을 잡힌 쪽","먼저 집을 지은 쪽","시간이 다 된 쪽"]],"kf":["1988년 아르헨티나에서 태어난 10×10 판의 2인용 게임","아마존을 여왕처럼 움직이고, 도착한 곳에서 화살을 쏘아 칸을 태운다","움직일 수 없게 된 쪽이 진다. 종반에는 바둑처럼 집을 센다"],"more":[{"h":"움직이고, 쏜다","p":["아마존은 다른 말이나 화살을 뛰어넘지 않는 한 몇 칸이든 움직일 수 있습니다. 그리고 도착한 칸에서 역시 여왕의 움직임으로 화살을 쏩니다. 방금 떠난 원래 칸에 쏴도 됩니다.","말을 잡는 일은 없습니다. 그 대신 한 수마다 판의 칸이 하나씩 쓸 수 없게 되고, 상대의 길을 막아 갑니다. 공격과 수비가 같은 한 발의 화살로 정해지는 것입니다."],"cap":["아마존스의 한 수. 백 아마존이 여왕처럼 움직이고(파랑), 도착한 곳에서 같은 방식으로 화살을 쏜다(빨강). 화살이 꽂힌 칸은 더는 지나갈 수 없다"]},{"h":"방으로 나뉘는 판","p":["게임이 진행되면 화살 벽으로 판이 여러 방으로 나뉩니다. 방 안에 한쪽 아마존만 있으면 그 방의 빈칸은 그 사람만의 것이 되어, 한 수에 한 칸씩 쓸 수 있습니다.","이렇게 되면 승부는 세기 싸움입니다. 쓸 수 있는 칸이 많은 쪽이 상대보다 오래 움직일 수 있습니다. 이 구조는 수학의 ‘조합 게임 이론’과 잘 맞아, 엘윈 벌캠프 등이 종반을 자세히 연구했습니다."],"cap":["종반의 판(이미지). 탄 칸의 벽으로 판이 네 방으로 나뉘었다. 초록은 백만, 파랑은 흑만 쓸 수 있는 방이며, 빈칸이 많은 쪽이 더 오래 움직일 수 있다"]},{"h":"잡지에서 태어나 컴퓨터로 겨룬다","p":["아마존스는 아르헨티나의 퍼즐 잡지에 처음 소개되었다고 합니다. 규칙이 짧고 체스판과 말만 있으면 할 수 있어, 인터넷을 통해 세계로 퍼졌습니다.","첫 수만으로도 2000가지가 넘는 수가 있어, 초반에는 바둑처럼 판 전체의 모양을 보는 힘이 필요합니다. 2000년대부터는 컴퓨터 대회의 종목이 되어 프로그램끼리 실력을 겨루고 있습니다."],"cap":[]}],"tl":[["1988년","왈테르 삼카우스카스가 아마존스를 고안"],["1990년대","인터넷을 통해 세계로 퍼짐"],["2000년","벌캠프가 종반에 관한 수학 연구 발표"],["2000년대","컴퓨터 올림피아드의 종목이 됨"]]},"loa":{"game":"라인스 오브 액션","title":"센 만큼 나아가는 말","lead":"1969년 시드 색슨의 책으로 세상에 나온 ‘라인스 오브 액션’. 말을 잡는 것이 아니라 자기 말을 모두 하나로 잇는 쪽이 이깁니다.","s":["라인스 오브 액션(LOA)은 8×8 판에서 각자 12개의 말을 움직이는 2인용 게임입니다. 클로드 수시가 고안했고, 1969년 게임 연구가 시드 색슨의 책 『A Gamut of Games』에서 소개되었습니다.","말은 가로·세로·대각선으로 곧게 나아갑니다. 몇 칸 가는지는 그 줄 위에 있는 말의 수(내 말과 상대 말 모두)와 정확히 같습니다. 말이 움직일 때마다 줄 위의 수가 바뀌고, 갈 수 있는 거리도 달라집니다.","내 말은 뛰어넘을 수 있지만 상대 말은 뛰어넘을 수 없습니다. 멈춘 칸에 상대 말이 있으면 그 말을 잡습니다.","목표는 내 말을 모두 가로·세로·대각선으로 이웃하게 하여 한 덩어리로 만드는 것입니다. 상대 말을 잡으면 상대의 수가 줄어 오히려 잇기 쉽게 만들어 줄 수도 있는, 신기한 게임입니다.","규칙은 짧지만 수읽기가 어려워 게임 AI 연구에도 자주 쓰였습니다. 네덜란드 마스트리흐트 대학의 프로그램은 컴퓨터 대회에서 여러 번 우승했습니다."],"quiz":[["말이 나아가는 칸 수를 정하는 것은?","그 줄 위에 있는 말의 수","주사위 눈","지금까지 잡은 말의 수","언제나 3칸으로 정해져 있다"],["LOA에서 이기는 것은 언제?","내 말을 모두 하나로 이었을 때","상대 말을 모두 잡았을 때","판의 반대쪽 끝에 닿았을 때","상대의 왕을 잡았을 때"],["1969년 책에서 LOA를 소개한 사람은?","시드 색슨","마틴 가드너","에드먼드 호일","H. J. R. 머리"]],"kf":["8×8 판에서 12개씩의 말로 하는 2인용 게임. 클로드 수시가 고안하고 1969년 시드 색슨의 책에서 소개됨","말은 그 줄 위에 있는 말의 수와 정확히 같은 칸만큼 나아간다. 내 말은 넘을 수 있지만 상대 말은 넘을 수 없다","많이 잡는 쪽이 아니라, 자기 말을 모두 하나로 먼저 이은 쪽이 이긴다"],"more":[{"h":"세고, 나아간다","p":["예를 들어 어떤 말을 지나는 가로줄에 말이 3개 있으면, 그 말은 가로로 정확히 3칸 나아갑니다. 더도 덜도 안 됩니다. 도중의 내 말은 넘어가도 되지만, 상대 말이 사이에 있으면 그 방향으로는 갈 수 없습니다.","말 하나에는 가로·세로·대각선 2개, 모두 4개의 줄이 있고 줄마다 수가 다릅니다. 말 하나가 움직이면 주변 여러 줄의 수가 바뀌므로, 한 수마다 판 위의 ‘거리’가 새로 짜입니다. 이 내다보기 어려움이 LOA의 재미입니다."],"cap":["화살표가 시작되는 흑 말이 갈 수 있는 곳. 가로줄에는 말이 3개 있으니 3칸(내 말은 넘어도 된다), 세로줄에는 2개이니 2칸 가서 백 말을 잡는다. 대각선도 3개지만 도중에 백 말이 있어 갈 수 없다(×)"]},{"h":"하나로 이으면 승리","p":["이어짐은 가로·세로·대각선의 이웃으로 셉니다. 말이 1개만 남은 사람도 ‘이어진’ 것이 되므로, 상대 말을 너무 많이 잡으면 상대를 이기게 해 주기도 합니다.","한 수로 양쪽이 동시에 이어졌을 때의 처리는 판본과 대회에 따라 다릅니다. 색슨의 책 초판에서는 무승부, 이후 판에서는 움직인 쪽의 승리였고, 오늘날 대회 대부분은 무승부로 합니다. 이 대백과의 LOA는 움직인 쪽의 승리입니다."],"cap":["이긴 모양. 백 말(금색 테)은 대각선을 포함한 이웃으로 한 덩어리가 되었다. 흑은 아직 세 덩어리로 나뉘어 있다(점선)"]},{"h":"컴퓨터가 겨룬 게임","p":["LOA는 판이 작고 규칙도 짧은데 수읽기가 깊어서 게임 AI 연구의 소재가 되었습니다. 마스트리흐트 대학의 마르크 위난츠가 만든 프로그램 ‘MIA’는 컴퓨터 올림피아드에서 2003·2004·2006·2009년에 우승했고, 그 연구는 2004년 박사 논문 『Informed Search in Complex Games』로 정리되었습니다.","2008년 위난츠는 판을 줄인 6×6 LOA를 풀어, 양쪽이 최선을 다하면 선수(흑)가 이긴다는 것을 보였습니다. 원래의 8×8 LOA는 아직 풀리지 않은 것으로 알려져 있습니다. 사람끼리의 세계 선수권도 마인드 스포츠 올림피아드에서 해마다 열립니다."],"cap":[]}],"tl":[["1960년경","클로드 수시가 LOA를 고안했다고 전해짐"],["1969년","시드 색슨의 『A Gamut of Games』에서 소개됨"],["2003년","위난츠의 MIA가 컴퓨터 올림피아드 우승(이후 2004·2006·2009년에도)"],["2004년","위난츠의 박사 논문 『Informed Search in Complex Games』"],["2008년","6×6 LOA가 풀려 선수의 승리로 밝혀짐"]]},"konane":{"title":"검은 용암과 흰 산호의 게임","lead":"하와이 사람들이 즐겨 온 ‘코나네’. 쿡의 항해 기록에 적혔고, 20세기에는 수학자들이 ‘조합 게임 이론’으로 연구했습니다.","s":["코나네는 하와이 원주민이 즐겨 온 2인용 게임입니다. 판의 칸에 검은 돌과 흰 돌을 번갈아 빈틈없이 놓고, 상대의 돌을 뛰어넘어 잡아 나갑니다.","옛날의 돌은 검은 것이 용암, 흰 것이 산호 조각이었습니다. 판은 ‘파파무’라고 불렸으며, 크고 평평한 돌 표면에 오목한 자리를 새겨 만들었습니다. 하와이의 창세 찬가 ‘쿠물리포’에도 이 게임이 나온다고 합니다.","처음에 흑이 자기 돌 하나를 들어내고, 백이 그 옆의 돌 하나를 들어냅니다. 이렇게 생긴 두 구멍에서 뛰어넘기가 시작됩니다.","모든 수는 ‘잡는 수’입니다. 돌은 가로·세로로 이웃한 상대 돌을 뛰어넘어 그 너머의 빈칸에 내려앉습니다. 곧게 가는 한 몇 번이든 이어서 뛸 수 있습니다.","잡을 수가 없어진 쪽이 지고, 무승부는 없습니다. 이 단순한 구조가 훗날 수학자들의 관심을 끌었습니다."],"quiz":[["코나네의 옛 흰 돌은 무엇으로 만들었을까?","산호","상아","흰 대리석","동물의 뼈"],["코나네에서 지는 쪽은?","잡을 수가 없어진 쪽","돌을 모두 잡힌 쪽","먼저 판 끝에 닿은 쪽","돌이 마지막에 하나만 남은 쪽"],["이어서 뛸 때 해서는 안 되는 것은?","도중에 방향을 바꾸는 것","한 번에 두 개 이상 잡는 것","도중에 멈추는 것","자기 돌 옆에 내려앉는 것"]],"kf":["하와이 원주민의 2인용 게임. 판 가득 검은(용암) 돌과 흰(산호) 돌을 번갈아 놓고 시작한다","모든 수는 가로·세로로 상대 돌을 뛰어넘어 잡는 수. 곧게 가면 이어서 뛸 수 있다","잡을 수가 없어진 쪽이 진다. 수학자들이 조합 게임 이론으로 연구했다"],"more":[{"h":"뛰어넘어 잡는다","p":["뛰어넘기는 가로·세로로만 하며, 대각선은 없습니다. 이웃한 상대 돌 너머가 비어 있으면 뛰어넘어 내려앉고, 뛰어넘은 돌을 판에서 들어냅니다.","내려앉은 곳에서 또 뛸 수 있으면 같은 방향 그대로 계속해도 됩니다. 다만 도중에 방향을 바꿀 수는 없고, 원하는 곳에서 멈춰도 됩니다. 한 수에 움직일 수 있는 돌은 하나뿐입니다."],"cap":["흰 돌이 한 수에 오른쪽으로 두 번 이어서 뛰어 검은 돌 둘을 잡는다(파란 1·2). 내려앉은 곳에서 아래로 방향을 바꿔 뛸 수는 없다(×)"]},{"h":"처음의 두 구멍","p":["돌로 가득 찬 판에서는 아무도 뛸 수 없습니다. 그래서 선수인 흑이 가운데 네 칸이나 네 귀퉁이에서 자기 돌 하나를 들어냅니다. 이어서 백이 그 구멍과 가로·세로로 이웃한 자기 돌 하나를 들어냅니다.","이렇게 나란히 생긴 두 구멍이 첫 착지점이 됩니다. 어디에 구멍을 내느냐에 따라 그 뒤의 흐름이 크게 달라집니다."],"cap":["두 가지 시작 방법. 흑이 판 가운데 네 칸(왼쪽)이나 네 귀퉁이(오른쪽)에서 자기 돌 하나를 들어내고(1), 백이 그 옆의 돌 하나를 들어낸다(2)"]},{"h":"돌판과 238개의 칸","p":["제임스 쿡의 제3차 항해 기록(1784년에 나온 제3권)에는 하와이에서 본 돌 게임이 “우리의 드래프츠(체커)와 아주 비슷하다”고, 다만 더 복잡하다고 적혀 있습니다. 쓴 사람은 장교 제임스 킹으로, 판은 길이 약 2피트에 한 줄 14칸, 모두 238칸이었다고 합니다.","판의 크기에는 정해진 것이 없어 6×7, 9×13, 13×20 등 여러 크기가 전해집니다. 요즘은 짝수의 정사각형 판에서 두는 일이 많고, 이 대백과에서는 6×6·8×8·10×10을 고를 수 있습니다. 하와이섬의 푸우호누아 오 호나우나우 국립역사공원에는 돌에 새긴 파파무가 남아 있습니다."],"cap":["판 크기 비교. 쿡의 항해 기록이 전하는 14×17(238칸) 판과, 이 대백과에서 둘 수 있는 10×10·8×8·6×6"]},{"h":"수학자가 찾아낸 게임","p":["‘움직일 수 없는 쪽이 진다’는 규칙에, 종반에는 판이 여러 독립된 부분으로 나뉘는 코나네는 엘윈 벌캠프 등의 ‘조합 게임 이론’으로 연구하기에 안성맞춤이었습니다. 마이클 언스트는 1993년 벌캠프와 코나네에 관한 짧은 글을 썼고, 1995년 논문에서 여러 국면의 값을 구했습니다.","그 뒤로도 한 줄짜리 코나네를 연구한 앨리스 챈과 앨리스 차이의 연구(2002년), 판을 키울수록 승패를 읽기가 극도로 어려워진다(PSPACE 완전)는 것을 보인 밥 헌의 연구가 이어졌습니다. 돌을 뛰어넘기만 하는 놀이가 계산 이론의 소재가 된 것입니다."],"cap":[]}],"tl":[["1778년","쿡의 배가 하와이에 도착"],["1784년","쿡의 제3차 항해 기록 출간, 킹이 쓴 돌 게임의 묘사가 실림"],["1993년","언스트와 벌캠프가 코나네에 관한 짧은 글을 씀"],["1995년","언스트의 논문 「Playing Konane Mathematically」"],["2002년","챈과 차이가 한 줄 코나네의 연구를 정리"]]},"peg":{"title":"궁정에서 태어난 혼자 하는 뛰어넘기 퍼즐","lead":"17세기 말 루이 14세의 프랑스 궁정에서 즐기던 ‘페그 솔리테르’. 말을 하나씩 줄여 가는 단순한 퍼즐에 수학자들도 빠져들었습니다.","s":["페그 솔리테르는 혼자 하는 퍼즐입니다. 판의 구멍에 말(페그)을 꽂고, 구멍 하나만 비워 둡니다.","말은 가로나 세로로 이웃한 말을 뛰어넘어 그 너머의 빈 구멍으로 옮깁니다. 뛰어넘긴 말은 판에서 빼냅니다.","목표는 계속 뛰어넘어 말을 마지막 하나만 남기는 것입니다. 한가운데 구멍에 하나만 남기면 완벽합니다.","확실한 기록이 남은 것은 17세기 말 프랑스, 루이 14세의 궁정입니다. 1697년 잡지 『메르퀴르 갈랑』에 판과 규칙이 실렸고, 판을 곁에 둔 귀부인의 판화도 만들어졌습니다.","쉬워 보여도 어렵습니다. 수학자 라이프니츠도 관심을 보였고, 20세기에는 수학자들이 구멍을 색칠하는 방법으로 왜 풀 수 없는 문제가 있는지를 설명했습니다."],"quiz":[["뛰어넘긴 말은 어떻게 될까?","판에서 빼낸다","상대의 말이 된다","옆 구멍으로 밀려난다","다음 차례에 돌아온다"],["영국식 판의 구멍은 몇 개?","33","37","45","64"],["페그 솔리테르의 확실한 기록이 처음 남은 곳은?","17세기 말 루이 14세의 프랑스 궁정","고대 로마의 목욕탕","에도 시대 일본의 서당","19세기 미국의 술집"]],"kf":["혼자 하는 뛰어넘기 퍼즐. 말을 뛰어넘어 빼내고, 마지막 하나를 남기면 성공","확실한 기록은 1697년경 루이 14세의 프랑스 궁정부터. 영국식 33구멍과 유럽식 37구멍 판이 있다","구멍을 세 가지 색으로 칠하면, 풀 수 없는 문제를 미리 가려낼 수 있다"],"more":[{"h":"뛰어넘어 빼낸다","p":["뛰어넘기는 가로·세로로만 하며 대각선으로는 할 수 없습니다(삼각형 판처럼 대각선 줄이 있는 판은 예외). 한 번 뛸 때마다 말이 하나씩 줄어드니, 32개로 시작하면 마지막 하나까지 31번 뛰게 됩니다.","같은 말이 연달아 몇 번을 뛰어도 됩니다. 연달아 뛴 것을 한 수로 세면, 영국식 판의 ‘가운데에서 가운데로’ 문제는 최소 18수로 풀립니다. 1912년 어니스트 버그홀트가 이 풀이를 찾았고, 1964년 존 비즐리가 더 짧게는 불가능하다는 것을 보였습니다."],"cap":["영국식 판의 첫 수. 가운데를 비운 판에서, 위의 말이 바로 아래 말을 뛰어넘어 가운데로 간다(파랑). 뛰어넘긴 말은 빼낸다(×)"]},{"h":"궁정의 놀이에서","p":["페그 솔리테르의 확실한 역사는 1697년경 루이 14세의 궁정으로 거슬러 올라갑니다. 그해 8월 잡지 『메르퀴르 갈랑』이 판과 규칙과 문제를 소개했고, 판화가 클로드오귀스트 베레는 판을 곁에 둔 수비즈 공비의 모습을 판화로 남겼습니다.","바스티유 감옥에 갇힌 귀족이 심심풀이로 이 퍼즐을 만들었다는 이야기도 유명하지만, 확인할 수 없는 전설입니다. 프랑스에서 쓰던 37구멍 판도 17세기부터 있었다고 하며, 모서리를 깎은 33구멍 판은 ‘영국식’이라고 불립니다."],"cap":["두 가지 대표적인 판. 영국식 33구멍(왼쪽)과 유럽식 37구멍(오른쪽). 빈 구멍은 각각 흔히 쓰는 시작 구멍"]},{"h":"세 가지 색으로 칠하면 보이는 것","p":["판의 구멍을 대각선으로 맞춰 세 가지 색으로 칠해 봅니다. 그러면 가로든 세로든 이어진 세 구멍은 반드시 세 색이 모두 다릅니다. 한 번 뛰면 두 색의 말이 하나씩 줄고 나머지 한 색이 하나 늘어나므로, 세 색의 개수의 ‘짝수·홀수’가 한꺼번에 뒤바뀝니다.","유럽식 판에서 가운데를 비우면 세 색 모두 12개로, 전부 짝수입니다. 뛸 때마다 ‘전부 짝수’와 ‘전부 홀수’가 바뀔 뿐이므로, 한 색이 1개이고 두 색이 0개인 ‘마지막 하나’의 모양에는 닿을 수 없습니다. 이 판에서는 가운데에서 시작하는 문제를 풀 수 없는 것입니다. 영국식 판을 같은 방법으로 살펴보면, 가운데에서 시작해 마지막 하나를 남길 수 있는 구멍은 다섯 곳으로 좁혀집니다."],"cap":["유럽식 37구멍 판을 대각선 줄마다 세 가지 색으로 칠한 것. 가운데를 비우면 어느 색이든 말이 12개씩이 된다"]},{"h":"수학자들의 놀이","p":["라이프니츠는 1710년의 메모에서 이 게임을 거꾸로, 즉 뛰어넘은 구멍을 다시 채워 가며 노는 것을 좋아한다고 썼다고 전해집니다. 끝의 모양에서 거꾸로 거슬러 가는 생각은 지금도 푸는 법의 기본입니다.","벌캠프, 콘웨이, 가이의 『Winning Ways』(1982년)는 이 퍼즐을 자세히 분석하고, 구멍에 점수를 매겨 ‘어떻게 뛰어도 합계가 늘지 않는다’는 것으로 불가능을 보이는 ‘파고다 함수’를 소개했습니다. 1999년에는 컴퓨터로 모든 국면을 다 조사한 결과도 나왔다고 합니다."],"cap":[]}],"tl":[["1697년","루이 14세의 궁정에서 즐겼고, 8월 『메르퀴르 갈랑』에 판과 규칙이 실림"],["1710년","라이프니츠가 거꾸로 푸는 놀이법에 대해 썼다고 전해짐"],["1912년","버그홀트가 영국식 판의 18수 풀이를 찾음"],["1964년","비즐리가 18수보다 짧은 풀이는 없음을 보임"],["1982년","『Winning Ways』가 파고다 함수 등의 분석을 정리"]]},"fanorona":{"title":"다가가서 잡고, 물러나서 잡는다","lead":"마다가스카르의 국민 게임 ‘파노로나’. 왕위를 정했다는 전설이 남아 있고, 21세기에는 컴퓨터가 ‘서로 최선을 다하면 무승부’임을 밝혀냈습니다.","s":["파노로나는 마다가스카르에서 널리 즐기는 2인용 게임입니다. 가로·세로·대각선이 그어진 9×5 판에서 각자 22개의 말을 씁니다.","판은 아랍 세계와 유럽에서 즐기던 ‘알케르케’의 판 두 개를 옆으로 나란히 놓은 모양입니다. 알케르케가 섬에 전해져 독자적인 게임으로 자랐다고 여겨집니다.","가장 큰 특징은 잡는 방법입니다. 상대 말 쪽으로 다가가는 ‘접근’이든, 상대 말에서 멀어지는 ‘이탈’이든, 그 줄에 늘어선 상대 말을 한꺼번에 잡을 수 있습니다.","잡을 수 있으면 반드시 잡아야 하고, 잡은 말은 방향을 바꿔 계속 잡을 수 있습니다. 한 수로 판의 모습이 확 바뀌는 것이 파노로나의 묘미입니다.","왕자가 게임에 빠져 왕위를 놓쳤다는 전설이 있을 만큼 오래전부터 사랑받아 왔습니다. 2007년 네덜란드의 연구자들은 컴퓨터로, 양쪽이 최선을 다하면 무승부가 된다는 것을 보였습니다."],"quiz":[["파노로나 판의 크기는?","9×5","8×8","7×7","6×6"],["파노로나에서 말을 잡는 두 가지 방법은?","다가가는 ‘접근’과 멀어지는 ‘이탈’","뛰어넘기와 끼우기","에워싸기와 부딪치기","주사위와 제비뽑기"],["컴퓨터가 밝힌, 서로 최선을 다했을 때의 결과는?","무승부","선수의 승리","후수의 승리","아직 아무것도 모른다"]],"kf":["마다가스카르의 2인용 게임. 9×5 판에 22개씩 놓고, 한가운데만 비우고 시작한다","상대 말에 다가가는 ‘접근’이나 멀어지는 ‘이탈’로, 줄에 늘어선 말을 한꺼번에 잡는다","2007년 컴퓨터가 ‘최선을 다하면 무승부’임을 보였다"],"more":[{"h":"다가가서 잡고, 물러나서 잡는다","p":["접근에서는 말이 한 걸음 움직인 곳 바로 앞에 상대 말이 있으면, 그 말과 같은 줄 너머로 끊기지 않고 늘어선 상대 말을 모두 잡습니다. 이탈은 그 반대로, 움직이기 전 바로 뒤에 있던 상대 말과 그 뒤에 늘어선 말을 잡습니다.","한 걸음에 여러 개가 한꺼번에 사라지므로, 초반부터 말이 크게 줄어듭니다. 접근과 이탈이 모두 가능한 수에서는 둘 중 하나를 고릅니다."],"cap":["두 가지 잡는 법. 위: 백이 오른쪽으로 한 걸음 나아가 흑에 다가가, 그 앞에 늘어선 흑 셋을 잡는다(접근). 아래: 백이 오른쪽으로 한 걸음 나아가 흑에서 멀어지며, 뒤에 늘어선 흑 둘을 잡는다(이탈)"]},{"h":"알케르케 두 개를 나란히 놓은 판","p":["판에는 5×9＝45개의 점이 있고, 가로·세로 줄 말고도 한 점 걸러 대각선이 지나갑니다. 말은 줄을 따라 이웃한 점으로 한 걸음씩 움직입니다. 처음에는 한가운데 한 점만 비어 있어서, 첫 수는 반드시 잡는 수가 됩니다.","이 판은 5×5 알케르케 판 두 개를 이어 붙인 모양입니다. 알케르케는 10세기 아랍의 책에도 이름이 보이는 오래된 게임으로, 파노로나는 여기서 생겨났다고 여겨집니다. 언제 어떻게 섬에 전해졌는지는 분명하지 않으며, 17세기경이라고 쓴 책도 있습니다."],"cap":["처음 배치. 9×5의 점에 흑백 22개씩. 비어 있는 것은 한가운데 한 점뿐. 점선 사각형은 5×5 알케르케 판 두 개"]},{"h":"계속 잡는 연쇄","p":["잡은 말은 이어서 또 잡을 수 있습니다. 다만 매번 다른 방향으로 움직여야 하고, 한 번 지나간 점으로 돌아갈 수도 없습니다. 계속할지는 자유입니다.","이런 연쇄가 잘 맞아떨어지면 한 수에 상대 말의 절반 가까이를 잡기도 합니다. 반대로 연쇄가 나쁜 자리에서 끝나면 곧바로 되잡히고 맙니다."],"cap":["연속 잡기의 예. 백이 (1) 오른쪽으로 다가가 둘, (2) 위로 물러나 둘, (3) 왼쪽으로 다가가 둘을 잡는다. (1) 다음에 계속 오른쪽으로 갈 수는 없다(×)"]},{"h":"왕위와 컴퓨터","p":["전설에 따르면 16세기경 이메리나의 왕 랄람부는 병든 척을 하며 먼저 돌아온 아들에게 왕위를 물려주려 했습니다. 형 안드리안톰포쿠인드린드라는 어려운 국면의 파노로나를 두다 멈추지 못했고, 동생 안드리안자카가 왕이 되었다고 합니다. 1895년 프랑스군이 침공했을 때 여왕 쪽이 의식으로 두는 파노로나 승부에 기댔다는 이야기도 전하지만, 둘 다 확인되지 않았습니다.","2007년 네덜란드 마스트리흐트 대학의 마르턴 스하트 등은 말이 7개 이하인 모든 국면을 조사하고, 증명수 탐색이라는 방법으로 처음 국면이 무승부임을 보였습니다(논문은 2008년). 계산에는 기계 한 대로 일주일 넘게 걸렸다고 합니다."],"cap":[]}],"tl":[["16세기경","랄람부 왕의 왕위 계승과 파노로나 전설"],["17세기경","파노로나가 알케르케에서 생겨났다는 한 가지 설"],["1895년","프랑스 침공 때 의식의 파노로나 전설"],["2007년","스하트 등이 컴퓨터로 ‘무승부’를 보임"],["2008년","논문 「Best Play in Fanorona Leads to Draw」"]]},"janggi":{"title":"강이 없는 판과, 딱 한 번 뛰는 포","lead":"한국에서 사랑받아 온 ‘장기’. 중국 상치와 같은 9×10 판을 쓰면서도 강을 없애고 말의 움직임을 크게 바꾸었습니다.","s":["장기는 한국에서 오래전부터 두어 온 2인용 게임입니다. 중국의 상치에서 나왔다고 여겨지며, 9×10 줄의 교차점에 말을 놓고 겨룹니다.","상치와 달리 판 가운데에 ‘강’이 없습니다. 상도 병도 판 어디로든 나아갈 수 있습니다. 장(왕)은 처음부터 ‘궁’의 한가운데에 있고, 궁 밖으로는 나갈 수 없습니다.","진영은 초(파랑·초록)와 한(빨강). 말은 팔각형이며, 강한 말일수록 크게 만듭니다. 선수는 초입니다.","대국 전에 각자 마와 상의 배치를 네 가지 중에서 고릅니다. 한이 먼저 차리고 초는 그것을 보고 정하므로, 상차림 때부터 수 싸움이 시작됩니다.","외통 말고 점수로 승부를 가리기도 합니다. 선수인 초는 72점, 후수인 한은 덤 1.5점을 받아 73.5점에서 시작하며, 말을 잃을수록 점수가 줄어듭니다."],"quiz":[["장기판에 없는 것은?","가운데의 강","궁","궁의 대각선","90개의 교차점"],["포가 움직일 때 반드시 필요한 것은?","말을 정확히 하나 뛰어넘는 것","상대 말 옆에 있는 것","궁 안에 있는 것","장군을 받지 않은 것"],["점수로 가릴 때 후수인 한에게 더하는 덤은?","1.5점","0.5점","3점","6.5점"]],"kf":["상치에서 나온 한국의 장기. 9×10 판이지만 가운데에 강이 없다","상은 직1·사2의 큰 움직임, 포는 말을 정확히 하나 뛰어넘어 움직이고 잡는다","마와 상의 상차림을 네 가지 중 골라 시작하며, 점수로 가릴 때 한에게 덤 1.5점"],"more":[{"h":"강 없는 판과 네 가지 상차림","p":["장기판은 상치와 같은 9×10 교차점이지만 가운데에 강이 없습니다. 양쪽 궁에는 ×자 모양의 대각선이 있어, 장과 사는 궁 안에서 이 대각선을 따라서도 한 칸씩 움직입니다. 장은 처음부터 궁의 한가운데에 놓입니다.","상차림은 마와 상의 자리를 바꾼 네 가지입니다. 한이 먼저 차리고, 초는 그것을 보고 자기 상차림을 정합니다. 상을 안쪽에 두느냐 바깥쪽에 두느냐에 따라 초반의 공격 길이 달라집니다."],"cap":["장기판과 처음 배치. 강은 없고, 위아래 궁에 대각선이 있다. 점선 원은 마와 상을 바꿀 수 있는 자리로, 위의 한과 아래의 초는 서로 다른 상차림을 골랐다"]},{"h":"마와 상, 막히는 자리","p":["마는 먼저 가로나 세로로 한 칸, 거기서 바깥쪽 대각선으로 한 칸 갑니다. 상은 더 크게, 가로나 세로로 한 칸, 거기서 대각선으로 두 칸 갑니다. 둘 다 가는 길의 점에 말이 있으면 그쪽으로는 갈 수 없습니다(멱).","상치의 상은 강을 건너지 못하고 대각선으로 두 칸만 움직이지만, 장기의 상은 판 어디든 갈 수 있는 긴 다리를 가진 말입니다. 대신 길이 막히기 쉬운 말이기도 합니다."],"cap":["마(왼쪽)는 직1·사1, 상(오른쪽)은 직1·사2. 파란 점이 갈 수 있는 곳. 가는 길의 점에 말이 있으면 그쪽으로는 갈 수 없다(×)"]},{"h":"딱 한 번 뛰는 포","p":["포는 움직일 때도 잡을 때도 반드시 사이의 말을 정확히 하나 뛰어넘습니다. 사이에 아무것도 없으면 한 칸도 움직일 수 없어서, 처음 국면에서 포는 움직이지 못합니다.","뛰어넘는 말도, 잡는 말도 포여서는 안 됩니다. 그래서 포끼리는 서로 노려보기만 할 뿐 손을 쓸 수 없습니다. 잡지 않을 때는 자유롭게 움직이는 상치의 포에 비하면 훨씬 까다로운 말입니다."],"cap":["포의 움직임. 위: 사이의 졸을 정확히 하나 뛰어넘어 그 너머의 점으로 가거나 차를 잡을 수 있다(파랑). 가운데: 사이의 말이 포면 넘을 수 없다. 아래: 포는 포를 잡을 수 없다(×)"]},{"h":"마주 보는 장과 점수","p":["두 장이 사이에 아무것도 없는 줄에서 마주 보는 것을 ‘빅장’이라고 합니다. 빅장을 당한 쪽이 그것을 풀지 않으면 무승부가 된다는 규칙이 있습니다. 또 전통 규칙에서는 장군을 받지 않았다면 한 수를 쉴 수도 있습니다(한수쉼).","점수는 차13·포7·마5·상3·사3·병2입니다. 초는 합계 72점, 한은 덤을 더해 73.5점입니다. 0.5점의 끝수가 있어서 점수로 가릴 때 동점이 나오지 않습니다. 이 대백과의 장기는 같은 국면이 세 번 되풀이되거나 200수에 이르면 이 점수로 승부를 정합니다."],"cap":[]}],"tl":[["고려 시대","이미 두었다고 보는 견해가 있다(전래 시기는 여러 설)"],["18세기","큰 판의 변종 ‘광상희’가 기록에 남았다고 한다"],["1895년","스튜어트 컬린의 『Korean Games』에 장기 두는 사람들의 그림이 실림"],["2009년","첫 국제 대회가 중국 하얼빈에서 열렸다고 한다"]]}};
